const hasJong = w => { const c=(w||"").trim().slice(-1).charCodeAt(0); return c>=0xAC00&&c<=0xD7A3 ? (c-0xAC00)%28>0 : null; };
const josa = (w,a,b) => { const j=hasJong(w); return w + (j===null ? `${a}(${b})` : j ? a : b); };
const num = s => { const t=String(s||"").replace(/,/g,""); const m=t.match(/(\d+(?:\.\d+)?)\s*(만)?/); if(!m) return 0; return Math.round(parseFloat(m[1])*(m[2]?10000:1)); };
