  o:["정해진 시간에 약을 먹을 수 있도록 일관된 지원이 필요함","약을 거부하는 이유를 이해하고 쉽게 설명하는 과정이 필요함","약과 관련된 변화는 의료기관과 공유할 필요가 있음"],
