   v.fact=[a.memo||"", ...(a.memo?[]:tp.map(x=>`${a.when?a.when+" ":""}${x} ${tail}`.trim()))].filter(Boolean).join(", ") + (a.memo&&tp.length?`, ${tp.join("·")} 관련 ${tail}`:"");
