    L.forEach(l=>{ let parts=l.split(/\s*\/\s*/); if(parts.length<2) parts=l.split(/\s*실적\s*/); const pl=parts[0], re=(parts[1]||"").replace(/실적\s*/,""); const P=parseSub(pl||""), Rr=String(re||"").replace(/(\d),(\d{3})/g,"$1$2");
      const done=+((Rr.match(/(\d+)\s*회/)||[])[1]||0), yeon=+((Rr.match(/연\s*인원\s*(\d+)/)||[])[1]||0); if(P&&!P.ppl) P.ppl=+((Rr.replace(/연\s*인원\s*\d+\s*명/,"").match(/(\d+)\s*명/)||[])[1]||0);
      const rate=P&&P.per&&done?Math.round(done/P.per*1000)/10:0;
      out.push(`${P?P.name:l}: 계획 ${P&&P.per?P.per+"회"+(P.basis===P.per+"회"?"":"("+P.basis+")"):"[확인 필요]"} / 실적 ${done?done+"회":"[확인 필요]"}${rate?` / 달성률 ${rate}%`:""}${P&&P.ppl&&done&&!yeon?` / 연인원 ${P.ppl*done}명(${P.ppl}명×${done}회)`:yeon?` / 연인원 ${yeon}명`:""}`); });
    const B=[...(v.budget||"").split("\n"),...(v.note||"").split("\n").filter(l=>/예산|집행/.test(l))].map(parseExec).filter(x=>x&&x.bud);
    if(!out.length && !B.length) return "";
