    sec("Ⅰ. 사업별 집행 총괄표");
    tbl(["사업","예산액(천원)","집행액(천원)","집행률","잔액(천원)"],R.length?[...R.map(r=>[r.name||"사업",chun(r.bud),r.used?chun(r.used):CK,r.used?r.rate+"%":"-",r.used?chun(r.rest):"-"]),["합계",chun(tb),chun(tu),rate+"%",chun(tb-tu)]]:[[CK,"","","",""]]);
