    box([...S.map(x=>`${x.name}: ${x.detail?x.detail+" – ":""}${subK(x.name).act}`),...(S.some(x=>x.pplAuto)?[`[자동 계산] 인원을 적지 않은 사업은 대상 인원(${PCTX.ppl}명)으로 계산함`]:[]),...(PCTX.range&&PCTX.months<12?[`[자동 계산] 사업 기간 ${PCTX.range}(${PCTX.months}개월) 기준으로 횟수를 계산함`]:[])]);
    if(g("focus")||g("prev")){ sec("Ⅳ. 중점 추진 사항"); box([...L("focus").map(x=>actOf(x)[0].replace(/(을|를) 진행함$/,"$1 중점적으로 추진함")),...L("prev").map(x=>`작년 결과 반영: ${x.replace(/[.。]$/,"")}`)]); }
    const n=(g("focus")||g("prev"))?["Ⅴ","Ⅵ","Ⅶ"]:["Ⅳ","Ⅴ","Ⅵ"];
