    const satL=L.filter(l=>/만족|좋아요|의견/.test(l));
    sec("Ⅶ. 만족도 조사 결과"); box([...satL.map(l=>{ const m=l.match(/(\d+)\s*명\s*중\s*(\d+)\s*명/); return m?`참여자 ${m[1]}명 중 ${m[2]}명(${r1p(+m[2],+m[1])}%)이 만족한다고 응답함${/의견/.test(l)?` / 주요 의견: ${l.replace(/.*?(만족|좋아요)[^,]*,?\s*/,"")}`:""}`:sentOf(l); }),...(g("sat")?reportFmt(g("sat")).split("\n"):[])]);
