    sec("Ⅳ. 세부사업 계획");
    tbl(["세부사업","연간 횟수(산출)","실인원","연인원(산출식)","예산(천원)","시기"],S.length?[...S.map(x=>[x.name,x.per?`${x.per}회(${x.basis})`:CK,x.ppl?x.ppl+"명":CK,x.yeon?`${x.yeon.toLocaleString("ko-KR")}명(${x.ppl}×${x.per})`:CK,x.bud?chun(x.bud)+(x.budBasis?`\n(${x.budBasis})`:""):"-",x.time||"연중"]),["합계","-","-",S.reduce((a,x)=>a+x.yeon,0).toLocaleString("ko-KR")+"명",tb?chun(tb):"-","-"]]:[[CK,"","","","",""]]);
    box([...S.map(x=>`${x.name}: ${x.detail?x.detail+" – ":""}${subK(x.name).act}`),...(S.some(x=>x.pplAuto)?[`[자동 계산] 인원을 적지 않은 사업은 대상 인원(${PCTX.ppl}명)으로 계산함`]:[]),...(PCTX.range&&PCTX.months<12?[`[자동 계산] 사업 기간 ${PCTX.range}(${PCTX.months}개월) 기준으로 횟수를 계산함`]:[])]);
