const nl = s => (s||"").replace(/\([^)]*\)|\[[^\]]*\]|[\s·:：,./\-ㆍ]/g,"").replace(/및/g,"및");
function matchKey(f, label){
  const L=nl(label); if(!L) return ""; let best="", score=0;
  f.fields.forEach(x=>{ const syn=[x.label,...(FSYN[x.k]||[])].map(nl).filter(Boolean); let s=0;
    syn.forEach(w=>{ if(w===L) s=Math.max(s,10+w.length); else if(L.length>=2 && w.length>=2 && (L.includes(w)||w.includes(L))) s=Math.max(s,Math.min(L.length,w.length)); });
    if(s>score){score=s;best=x.k;} });
  return score>=2?best:"";
}
async function parseTemplate(file){
  const name=file.name, low=name.toLowerCase();
  if(low.endsWith(".docx")||low.endsWith(".hwpx")){
    const ext=low.endsWith(".docx")?"docx":"hwpx", z=await unzip(file), T=ext==="docx"?DOCX_T:HWPX_T;
    const targets= ext==="docx" ? ["word/document.xml"] : z.names.filter(n=>/^Contents\/section\d+\.xml$/i.test(n)).sort();
    const docs={}, fields=[];
    for(const n of targets){ const d=new DOMParser().parseFromString(await z.text(n),"application/xml"); docs[n]=d; findFields(d,T).forEach(x=>{x.part=n; fields.push(x);}); }
    return {name, ext, z, docs, fields, mode:"same"};
  }
  if(low.endsWith(".pdf")){ const labels=await pdfLabels(file); return {name, ext:"pdf", fields:labels.map(l=>({label:l,value:""})), mode:"new"}; }
  if(low.endsWith(".hwp")) return {name, ext:"hwp", fields:[], mode:"new", hwp:1};
  throw new Error("type");
}
async function attachTemplate(f, file){
  const st=document.getElementById("fstatus")||document.getElementById("ad-status"); if(st){ st.classList.remove("warn"); st.textContent="첨부한 서식을 읽는 중이에요…"; }
  try{
    const a=await parseTemplate(file);
    if(a.hwp){ if(st){ st.textContent="예전 한글(.hwp)은 바로 바꿀 수 없어요. 한글에서 ‘다른 이름으로 저장 → 한글 문서(.hwpx) 또는 Word 문서(.docx)’로 저장해 다시 올려 주세요."; st.classList.add("warn"); } return false; }
    if(!a.fields.length){ if(st){ st.textContent="첨부 서식에서 채울 칸을 찾지 못했어요. 표 안에 ‘항목 칸 + 빈 칸’이 있는 서식이면 자동으로 바뀌어요."; st.classList.add("warn"); } return false; }
    const used=new Set();
    a.fields.forEach(x=>{ const k=matchKey(f,x.label.replace(/\s*\(\d+\)$/,"")); x.key = k && !used.has(k) ? k : ""; if(x.key) used.add(x.key); if(!x.grid){ const val=attValue(f,x.key); if(val) x.value=val; } });
    a.memo=""; ATT[f.id]=a; await myfSave(f,file); renderForm(f); myfSaveVals(f);
    return true;
  }catch(e){ if(st){ st.textContent="서식을 읽지 못했어요. 워드(.docx)나 한글(.hwpx) 파일로 첨부해 주세요."; st.classList.add("warn"); } return false; }
}
function attValue(f,k){ if(!k) return ""; return fv(f,getF(f),k); }
function attBoxHTML(f){
  const a=ATT[f.id]; if(!a) return "";
  const opts=k=>`<option value="">비워두기</option>${f.fields.map(x=>`<option value="${x.k}"${x.k===k?" selected":""}>${esc(x.label)}</option>`).join("")}`;
  const kind = a.mode==="same" ? (a.ext==="docx"?"워드 서식 모양 그대로 채워져요.":"한글(.hwpx) 서식 모양 그대로 채워져요. 한글에서 열어 확인하세요.") : "PDF는 모양을 그대로 쓸 수 없어서, 같은 항목 순서의 새 워드 서식으로 만들어요.";
  return `<div class="attbox"><div class="attbox-h"><b>첨부한 서식</b><span>${esc(a.name)}</span><button type="button" class="pill" id="fatt-off">첨부 해제</button></div>
    <p class="attbox-n">${kind} 왼쪽 칸 내용이 아래처럼 연결돼요.</p>
    <table class="atttbl"><thead><tr><th>내 서식의 칸</th><th>넣을 내용</th></tr></thead><tbody>
    ${a.fields.map((x,i)=>`<tr><td>${esc(x.label)}</td><td><select data-amap="${i}" aria-label="${esc(x.label)}에 넣을 내용">${opts(x.key)}</select><small>${esc((attValue(f,x.key)||"").slice(0,40))||"(빈칸)"}</small></td></tr>`).join("")||`<tr><td colspan="2">찾은 칸이 없어요.</td></tr>`}
    </tbody></table>
    <div class="attbox-b"><button type="button" class="btn-sm main" id="fatt-down">내 서식으로 받기</button><button type="button" class="btn-sm" id="fdown-base">앱 기본 서식으로 받기</button></div>
  </div>`;
}
async function downloadAttached(f){
  const a=ATT[f.id], st=document.getElementById("fstatus"), keep=up;
  a.fields.forEach(x=>{ x.value=attValue(f,x.key); });
  const base=(getF(f).title||a.name.replace(/\.[^.]+$/,"")).replace(/[\\/:*?"<>|]/g,"").trim();
  try{ up=a;
    if(a.mode==="same"){ const blob=await buildFilled(); await saveFile(`${base}_작성.${a.ext}`, blob, st); }
    else await saveFile(`${base}_작성.docx`, upNewDocx(), st);
  }catch(e){ st.textContent="첨부 서식으로 만들지 못했어요. ‘앱 기본 서식으로 받기’를 이용해 주세요."; st.classList.add("warn"); }
  finally{ up=keep; }
}

/* ================= 내 서식 모드: 시설 서식을 올리면 입력칸·미리보기가 그 서식으로 바뀜 ================= */
const myfText=(n,T)=>Array.from(n.getElementsByTagName(T.t)).map(x=>x.textContent).join("").trim();
const myfKids=(n,name)=>Array.from(n.childNodes).filter(c=>c.nodeName===name);
function myfCellsOf(tr,T){ return myfKids(tr,T.tc); }
function myfRowsOf(tbl,T){ return myfKids(tbl,T.tr); }
function myfTopBlock(node,T){ /* 표·문단이 본문에서 차지하는 최상위 문단(또는 표) 찾기 */
  let n=node; while(n.parentNode && n.parentNode.nodeType===1 && !/(:body|:sec)$/.test(n.parentNode.nodeName)) n=n.parentNode; return n; }
function myfHeading(tbl,T){ /* 표 바로 위의 글(제목) */
  let n=myfTopBlock(tbl,T).previousSibling, k=0;
  while(n && k<4){ if(n.nodeType===1){ if(n.nodeName===T.tbl) break; const t=myfText(n,T); if(t && t.length<=50 && !n.getElementsByTagName(T.tbl).length) return cleanLabel(t.replace(/^▶\s*작성\s*요령.*$/,"")); k++; } n=n.previousSibling; }
  return ""; }
function findFields(doc, T){
  const fields=[], used=new Set();
  const tbls=Array.from(doc.getElementsByTagName(T.tbl));
  for(const tbl of tbls){
    const rows=myfRowsOf(tbl,T); if(!rows.length) continue;
    const R=rows.map(r=>myfCellsOf(r,T)), X=R.map(r=>r.map(c=>myfText(c,T)));
    const head=myfHeading(tbl,T);
    /* 결재란 표는 건너뜀 */
    if(X.flat().some(t=>/^결\s*재$|^결$/.test(t)) || (X[0].length>=2 && X[0].every(t=>/^(결|재|결재|담당|검토|팀장|사무국장|국장|부장|원장|시설장|대표)$/.test(t.replace(/\s/g,""))))) continue;
    const hdrOk = R[0].length>=2 && X[0].every(isLabel) && R.slice(1).some(r=>r.length===R[0].length);
    if(hdrOk){
      /* ① 머리줄 + 완전히 빈 줄들 → 표 한 개를 한 칸으로 (한 줄 = 한 행, 칸은 / 로 구분) */
      const emptyRows=R.slice(1).filter((r,k)=>X[k+1].every(t=>!t) && !r.some(c=>c.getElementsByTagName(T.tbl).length));
      if(emptyRows.length){ fields.push({label:(head||X[0].join("·")).slice(0,40), grid:emptyRows, cols:(emptyRows[0].length===R[0].length?X[0]:emptyRows[0].map((_,k)=>`칸${k+1}`)).slice(), value:""}); emptyRows.flat().forEach(c=>used.add(c)); }
      /* ①-2 번호(1,2,3…)만 적힌 줄들 → 표 한 개를 한 칸으로 */
      const numRows=R.slice(1).filter((r,k)=>r.length===R[0].length && /^\d+[.)]?$/.test(X[k+1][0]) && X[k+1].slice(1).every(t=>!t) && !used.has(r[1]));
      if(numRows.length>=2){ fields.push({label:(head||X[0].join("·")).slice(0,40), grid:numRows.map(r=>r.slice(1)), cols:X[0].slice(1), value:""}); numRows.forEach(r=>r.forEach(c=>used.add(c))); }
      /* ② 앞쪽은 적혀 있고 뒤쪽이 빈 줄 → 줄마다 한 칸 (적힌 글이 칸 이름) */
      R.forEach((r,k)=>{ if(!k) return; const t=X[k]; const emp=r.filter((c,q)=>!t[q] && !used.has(c)); if(!emp.length || emp.length===r.length) return;
        let lab=t.filter(Boolean).slice(0,2).join(" · ").slice(0,36); if(!lab) return; if(/^\d+[.)]?$/.test(lab)) lab=`${head||"표"} ${parseInt(lab)}번 줄`;
        const cols=emp.map(c=>{ const q=r.indexOf(c); return r.length===R[0].length?X[0][q]:`칸${q+1}`; });
        fields.push(emp.length===1?{label:lab, cell:emp[0], value:"", hint:cols[0]}:{label:lab, grid:[emp], cols, value:""}); emp.forEach(c=>used.add(c)); });
      R.flat().forEach(c=>used.add(c));
    }
    /* ③ '항목 칸 + 빈 칸' 짝 (□ 고르기 칸 포함) */
    R.forEach((r,i)=>{ for(let j=0;j<r.length-1;j++){ const a=X[i][j], b=X[i][j+1];
      if(isLabel(a) && /[□☐]/.test(b) && !used.has(r[j+1])){ const opts=myfOpts(b); if(opts.length>=2){ fields.push({label:cleanLabel(a), cell:r[j+1], labelCell:r[j], value:"", check:1, opts}); used.add(r[j+1]); j++; continue; } }
      if(isLabel(a) && !b && !used.has(r[j+1])){ fields.push({label:cleanLabel(a), cell:r[j+1], labelCell:r[j], value:""}); used.add(r[j+1]); j++; } } });
    /* ④ 한 칸짜리 빈 상자 → 위 제목을 칸 이름으로 */
    R.forEach((r,i)=>{ if(r.length===1 && !X[i][0] && !used.has(r[0]) && !r[0].getElementsByTagName(T.tbl).length){
      const prev = i>0 && R[i-1].length===1 ? X[i-1][0] : "";
      fields.push({label:cleanLabel(prev||head||"내용").slice(0,40), cell:r[0], value:"", box:1}); used.add(r[0]); } });
  }
  /* ⑤ 표 밖 '항목:' 문단 */
  for(const p of doc.getElementsByTagName(T.p)){
    let anc=p.parentNode, inTbl=false; while(anc){ if(anc.nodeName===T.tc){inTbl=true;break;} anc=anc.parentNode; }
    if(inTbl) continue;
    const t=myfText(p,T); const m=t.match(/^(.{1,20}?)\s*[:：]\s*$/);
    if(m) fields.push({label:cleanLabel(m[1]), para:p, value:""});
  }
  /* 문서 순서대로 정렬 */
  const anchor=f=>f.cell||f.para||f.grid[0][0];
  fields.sort((a,b)=>{ const x=anchor(a), y=anchor(b); if(x===y) return 0; return x.compareDocumentPosition(y)&Node.DOCUMENT_POSITION_FOLLOWING?-1:1; });
  const seen={}; fields.forEach(f=>{ seen[f.label]=(seen[f.label]||0)+1; if(seen[f.label]>1) f.label+=` (${seen[f.label]})`; });
  return fields;
}
const DOCX_T={tr:"w:tr",tc:"w:tc",p:"w:p",t:"w:t",tbl:"w:tbl"}, HWPX_T={tr:"hp:tr",tc:"hp:tc",p:"hp:p",t:"hp:t",tbl:"hp:tbl"};
/* 표 칸 값 나누기: 한 줄 = 한 행, 칸은 / | 탭 으로 구분 */
function myfGridVals(f){ const lines=String(f.value||"").split("\n").map(s=>s.trim()).filter(Boolean), out=[];
  f.grid.forEach((row,ri)=>{ let ln=lines[ri]||""; if(ri===f.grid.length-1 && lines.length>f.grid.length) ln=[ln,...lines.slice(f.grid.length)].join(" / ");
    const parts=ln?ln.split(/\s*[\/|\t]\s*/):[]; out.push(row.map((c,ci)=>ci===row.length-1?parts.slice(ci).join(" / "):(parts[ci]||""))); });
  return out; }
function myfFill(clone,map,f,ext){
  const put=(cell,val)=>{ if(!val) return; const c=map.get(cell); if(!c) return; if(ext==="docx") fillDocxCell(clone,c,val); else fillHwpx(clone,{cell:c,value:val}); };
  if(f.grid){ const G=myfGridVals(f); f.grid.forEach((row,ri)=>row.forEach((c,ci)=>put(c,G[ri][ci]))); return; }
  if(!(f.value||"").trim()) return;
  if(f.check){ const c=map.get(f.cell); if(c) myfCheck(c,f,ext==="docx"?DOCX_T:HWPX_T); return; }
  if(ext==="docx"){ if(f.cell) fillDocxCell(clone,map.get(f.cell),f.value); else if(f.para) fillDocxPara(clone,map.get(f.para),f.value); }
  else fillHwpx(clone,{...f,cell:f.cell&&map.get(f.cell),labelCell:f.labelCell&&map.get(f.labelCell),para:f.para&&map.get(f.para)});
}
async function buildFilled(){
  const ser=new XMLSerializer(), changed={};
  for(const part of Object.keys(up.docs)){
    const d=up.docs[part], clone=d.cloneNode(true), map=new Map();
    const all=Array.from(d.getElementsByTagName("*")), allC=Array.from(clone.getElementsByTagName("*")); all.forEach((n,i)=>map.set(n,allC[i]));
    up.fields.filter(f=>(f.part||part)===part).forEach(f=>myfFill(clone,map,f,up.ext));
    changed[part]=ser.serializeToString(clone);
  }
  return await rezip(changed);
}
/* ---- 내 서식 미리보기 (원본 모양 + 입력 값을 파란 글씨로) ---- */
function myfValueMaps(a){ const vm=new Map(), pm=new Map();
  a.fields.forEach(f=>{ if(f.grid){ const G=myfGridVals(f); f.grid.forEach((row,ri)=>row.forEach((c,ci)=>{ if(G[ri][ci]) vm.set(c,G[ri][ci]); })); }
    else if(f.check) return; else if(f.cell && (f.value||"").trim()) vm.set(f.cell,f.value); else if(f.para && (f.value||"").trim()) pm.set(f.para,f.value); });
  return {vm,pm}; }
const myfV=v=>`<span class="dp-v">${esc(v).replace(/\n/g,"<br>")}</span>`;
function myfDocxHTML(doc,vm,pm){
  const W="w:";
  const runText=p=>{ let h=""; p.getElementsByTagName("*"); for(const r of Array.from(p.getElementsByTagName(W+"r"))){ for(const c of Array.from(r.childNodes)){ if(c.nodeName===W+"t") h+=esc(c.textContent); else if(c.nodeName===W+"br") h+="<br>"; else if(c.nodeName===W+"tab") h+="&emsp;"; } } return h; };
  const para=p=>{ const jc=p.getElementsByTagName(W+"jc")[0], al=jc&&jc.getAttribute("w:val"); const b=p.getElementsByTagName(W+"b").length>0;
    const sz=p.getElementsByTagName(W+"sz")[0], s=sz?+sz.getAttribute("w:val"):0; const col=p.getElementsByTagName(W+"color")[0], cv=col&&col.getAttribute("w:val");
    let h=runText(p); if(pm.has(p)) h+=" "+myfV(pm.get(p));
    const st=[al==="center"?"text-align:center":al==="right"||al==="end"?"text-align:right":"", b?"font-weight:700":"", s>=30?"font-size:1.35em":s>=24?"font-size:1.12em":s&&s<=17?"font-size:.86em":"", cv&&cv!=="auto"&&cv!=="000000"?`color:#${cv}`:""].filter(Boolean).join(";");
    return `<p class="dp-p"${st?` style="${st}"`:""}>${h||"&nbsp;"}</p>`; };
  const cellHTML=tc=>{ if(vm.has(tc) && !myfText(tc,DOCX_T)) return `<p class="dp-p">${myfV(vm.get(tc))}</p>`; let h=""; for(const c of Array.from(tc.childNodes)){ if(c.nodeName===W+"p") h+=para(c); else if(c.nodeName===W+"tbl") h+=tbl(c); } if(vm.has(tc)) h+=`<p class="dp-p">${myfV(vm.get(tc))}</p>`; return h; };
  const tbl=t=>{ const rows=Array.from(t.childNodes).filter(n=>n.nodeName===W+"tr"); const open={}; const M=[];
    rows.forEach(tr=>{ let col=0; const line=[];
      Array.from(tr.childNodes).filter(n=>n.nodeName===W+"tc").forEach(tc=>{ const pr=Array.from(tc.childNodes).find(n=>n.nodeName===W+"tcPr");
        const gs=pr&&Array.from(pr.childNodes).find(n=>n.nodeName===W+"gridSpan"), span=gs?(+gs.getAttribute("w:val")||1):1;
        const vmg=pr&&Array.from(pr.childNodes).find(n=>n.nodeName===W+"vMerge"), vval=vmg&&vmg.getAttribute("w:val");
        const shd=pr&&Array.from(pr.childNodes).find(n=>n.nodeName===W+"shd"), fill=shd&&shd.getAttribute("w:fill");
        if(vmg && vval!=="restart" && open[col]){ open[col].rs++; if(vm.has(tc)) open[col].extra+=myfV(vm.get(tc)); col+=span; return; }
        const o={tc,span,rs:1,fill:fill&&fill!=="auto"?fill:"",extra:""}; line.push(o); if(vmg) open[col]=o; else delete open[col]; col+=span; });
      M.push(line); });
    return `<table class="dp-t">${M.map(line=>`<tr>${line.map(o=>`<td${o.span>1?` colspan="${o.span}"`:""}${o.rs>1?` rowspan="${o.rs}"`:""}${o.fill?` style="background:#${o.fill}"`:""}>${cellHTML(o.tc)}${o.extra}</td>`).join("")}</tr>`).join("")}</table>`; };
  const body=doc.getElementsByTagName(W+"body")[0]; if(!body) return "";
  let h="", empties=0;
  for(const c of Array.from(body.childNodes)){ if(c.nodeName===W+"p"){ const x=para(c); if(x.includes(">&nbsp;</p>")){ if(++empties>2) continue; } else empties=0; h+=x; } else if(c.nodeName===W+"tbl"){ empties=0; h+=tbl(c); } }
  return h; }
function myfHwpxHTML(doc,vm,pm){
  const P="hp:";
  const para=p=>{ let h="", tb=""; for(const r of Array.from(p.childNodes)){ if(r.nodeName!==P+"run") continue;
      for(const c of Array.from(r.childNodes)){ if(c.nodeName===P+"t") h+=esc(c.textContent); else if(c.nodeName===P+"tbl") tb+=tbl(c); else if(c.nodeName===P+"ctrl"){ Array.from(c.getElementsByTagName(P+"tbl")).forEach(t=>{ tb+=tbl(t); }); } } }
    if(pm.has(p)) h+=" "+myfV(pm.get(p));
    return (h?`<p class="dp-p">${h}</p>`:(tb?"":`<p class="dp-p">&nbsp;</p>`))+tb; };
  const cellHTML=tc=>{ if(vm.has(tc) && !myfText(tc,HWPX_T)) return `<p class="dp-p">${myfV(vm.get(tc))}</p>`; let h=""; Array.from(tc.getElementsByTagName(P+"p")).filter(p=>{ let a=p.parentNode; while(a&&a!==tc){ if(a.nodeName===P+"tc") return false; a=a.parentNode; } return true; }).forEach(p=>{ h+=para(p); }); if(vm.has(tc)) h+=`<p class="dp-p">${myfV(vm.get(tc))}</p>`; return h; };
  const tbl=t=>`<table class="dp-t">${Array.from(t.childNodes).filter(n=>n.nodeName===P+"tr").map(tr=>`<tr>${Array.from(tr.childNodes).filter(n=>n.nodeName===P+"tc").map(tc=>{ const sp=Array.from(tc.childNodes).find(n=>n.nodeName===P+"cellSpan"); const cs=sp?+sp.getAttribute("colSpan")||1:1, rs=sp?+sp.getAttribute("rowSpan")||1:1;
      return `<td${cs>1?` colspan="${cs}"`:""}${rs>1?` rowspan="${rs}"`:""}>${cellHTML(tc)}</td>`; }).join("")}</tr>`).join("")}</table>`;
  const root=doc.documentElement; let h="";
  for(const c of Array.from(root.childNodes)) if(c.nodeName===P+"p") h+=para(c);
  return h; }
function myfPreview(a){
  try{
    if(a.mode==="same" && a.docs){ const {vm,pm}=myfValueMaps(a); let h=""; const undo=[];
      a.fields.forEach(x=>{ if(x.check && x.cell && (x.value||"").trim()) undo.push(...myfCheck(x.cell,x,a.ext==="docx"?DOCX_T:HWPX_T,true)); });
      try{ for(const part of Object.keys(a.docs)) h+= a.ext==="docx" ? myfDocxHTML(a.docs[part],vm,pm) : myfHwpxHTML(a.docs[part],vm,pm); }
      finally{ undo.forEach(([n,t])=>{ n.textContent=t; }); }
      return h || `<p class="hint">미리보기를 만들 수 없는 서식이에요. ‘내 서식으로 받기’로 확인해 주세요.</p>`; }
    return `<h3 style="text-align:center">${esc(a.name.replace(/\.[^.]+$/,""))}</h3><table class="dp-t">${a.fields.map(f=>`<tr><th>${esc(f.label)}</th><td>${f.value?myfV(f.value):""}</td></tr>`).join("")}</table><p class="hint">PDF는 모양 그대로 쓸 수 없어 같은 항목 순서의 새 워드 서식으로 받아요.</p>`;
  }catch(e){ return `<p class="hint">미리보기를 만드는 중 문제가 생겼어요. ‘내 서식으로 받기’는 그대로 쓸 수 있어요.</p>`; }
}
/* ---- 내 서식 화면 ---- */
function myfPrompt(f,a){
  const org=(PROF.name||"").trim()||"[시설명]", D=f.kind==="aidoc"?AIDOC[f.doc]:null, memo=(a.memo||"").trim();
  const done=a.fields.filter(x=>(x.value||"").trim());
  const L=[`너는 장애인복지관 행정 문서를 오래 써 온 사회복지 전문가야. 사회복지시설평가 현장평가위원이 읽어도 근거가 분명한 수준으로 써줘.`,
   `\n[작성할 문서] ${org}의 「${f.name}」 — 우리 시설 서식(${a.name})의 칸을 채워줘.`,
   `\n[서식 칸] 아래 칸 이름을 【 】 그대로 쓰고, 그 아래에 들어갈 내용을 써줘. 표 칸은 한 줄에 한 행씩 쓰고 칸 사이는 / 로 나눠줘.`,
   a.fields.map(x=>`【${x.label}】${x.grid?` (표: ${x.cols.join(" / ")}, ${x.grid.length}행)`:x.check?` (고르기: ${x.opts.join(" / ")} 중에서 골라 그 이름만 써줘)`:""}`).join("\n")];
  if(done.length) L.push(`\n[이미 적은 내용] (이 사실과 숫자만 사용)\n${done.map(x=>`- ${x.label}: ${x.value.replace(/\n/g," / ")}`).join("\n")}`);
  L.push(`\n[메모]\n${memo||"[메모를 적어 주세요]"}`);
  if(D) L.push(`\n[2026년 장애인장애인복지관 평가지표 반영]\n${D.ind.map(k=>"- "+IND[k]).join("\n")}`);
  L.push(`\n[작성 원칙]\n1. 내가 준 자료에 없는 숫자, 날짜, 횟수, 금액, 성과는 만들지 말고 [확인 필요]로 써.\n2. 개조식(○, -)으로 쓰고 문장 끝은 '~함, ~임, ~됨'으로 맞춰.\n3. 이용자 이름은 ○○님, 직원은 직위로 쓰고 주민등록번호·연락처·진단명은 넣지 마.\n4. 금액은 천원 단위, 연인원 = 실인원 × 횟수로 계산하고 검산해.\n5. 서식에 없는 칸을 새로 만들지 마.`);
  L.push(`\n[진행 순서] 바로 완성본을 쓰지 말고, 아래 순서대로 나와 대화하며 진행해줘.\n1단계(1차 기획안): 칸별로 들어갈 핵심 내용 1~2줄과 [확인 필요] 목록을 먼저 보여줘.\n2단계(확인 질문): "수정할 부분이 있으면 알려 주세요. 이대로 괜찮으면 '초안 작성'이라고 말씀해 주시면 바로 ${f.name} 초안을 작성할게요."라고 물어봐줘.\n3단계(수정): 내가 고칠 내용을 말하면 그 부분만 고친 기획안을 다시 보여주고 "수정한 내용이 맞나요? 맞으면 '초안 작성'이라고 말씀해 주시면 바로 작성할게요."라고 물어봐줘.\n4단계(작성): 내가 '초안 작성' 또는 '네', '좋아요', '그대로 해 주세요', '작성해 주세요', '진행해 주세요', 'OK'처럼 동의하는 말을 하면 더 묻지 말고, 위 【칸 이름】 형식 그대로 모든 칸을 채워 써줘. (앱에 그대로 붙여 넣을 수 있게)`);
  return L.join("\n"); }
function myfFieldHTML(x,i){ if(x.check) return myfCheckHTML(x,i); const rows=x.grid?Math.max(2,Math.min(10,x.grid.length+1)):x.box?4:x.para?1:2;
  return `<div class="field"><label for="myf-${i}">${esc(x.label)}${x.grid?(x.grid.length>1?` <small>(표 ${x.grid.length}행 · 한 줄에 한 행 · 칸은 / 로 구분)</small>`:` <small>(${esc(x.cols.join(" / "))} · / 로 구분)</small>`):x.hint?` <small>(${esc(x.hint)})</small>`:""}</label><div class="with-mic"><textarea id="myf-${i}" data-myf="${i}" rows="${rows}" placeholder="${x.grid?esc(x.cols.join(" / ")):""}">${esc(x.value||"")}</textarea>${hasMic?`<button type="button" class="mic b3d" data-myfmic="${i}" aria-label="${esc(x.label)} 말로 입력">${ico("mic")}</button>`:""}</div>${x.grid?`<div class="ex-hint"><span>예: ${esc(x.cols.map((c,k)=>k?"○○":"내용").join(" / "))} (한 줄에 한 행)</span></div>`:""}</div>`; }
/* ---- 고르기 칸(□ 대면 □ 전화 …) ---- */
function myfOpts(t){ return String(t||"").split(/[□☐■☑]/).slice(1).map(s=>s.replace(/[(:：]\s*$/,"").trim()).filter(s=>s && s.length<=20); }
function myfPicked(x){ const v=String(x.value||"").replace(/\s/g,""); if(!v) return []; const toks=String(x.value).split(/[,，、·\/\n]+/).map(s=>s.replace(/\s/g,"")).filter(Boolean);
  let on=x.opts.filter(o=>{ const n=o.replace(/\s/g,""); return toks.includes(n) || (n.length>=2 && v.includes(n)) || toks.some(t=>t.length>=2 && n.includes(t)); });
  if(!on.length){ const etc=x.opts.find(o=>/^기타/.test(o.replace(/\s/g,""))); if(etc) on=[etc]; }
  return on; }
function myfCheck(cell,x,T,keep){ /* 고른 항목의 □를 ■로 (글자 하나만 바꿔 모양 유지) */
  const nodes=Array.from(cell.getElementsByTagName(T.t)); let full="", pos=[]; nodes.forEach(n=>{ pos.push(full.length); full+=n.textContent; });
  const on=new Set(myfPicked(x).map(o=>o.replace(/\s/g,""))), undo=[], hit=[];
  const re=/[□☐]/g; let m; const marks=[]; while((m=re.exec(full))) marks.push(m.index);
  marks.forEach((at,k)=>{ const nx=k+1<marks.length?marks[k+1]:full.length; const opt=full.slice(at+1,nx).replace(/[(:：]\s*$/,"").replace(/\s/g,""); if(on.has(opt)) hit.push(at); });
  hit.forEach(at=>{ let ni=0; while(ni+1<nodes.length && pos[ni+1]<=at) ni++; const n=nodes[ni], off=at-pos[ni], t=n.textContent; if(keep && !undo.some(u=>u[0]===n)) undo.push([n,t]); n.textContent=t.slice(0,off)+"■"+t.slice(off+1); });
  return undo; }
function myfCheckHTML(x,i){ const on=myfPicked(x); return `<div class="field"><label>${esc(x.label)} <small>(고르기)</small></label><div class="chips">${x.opts.map(o=>`<label class="chip"><input type="checkbox" data-myfchk="${i}" value="${esc(o)}" ${on.includes(o)?"checked":""}><span>${esc(o)}</span></label>`).join("")}</div></div>`; }
document.addEventListener("change",e=>{ const el=e.target.closest("[data-myfchk]"); if(!el || !curForm || !ATT[curForm.id]) return; const a=ATT[curForm.id], i=+el.dataset.myfchk, x=a.fields[i]; if(!x) return;
  x.value=Array.from(document.querySelectorAll(`[data-myfchk="${i}"]`)).filter(c=>c.checked).map(c=>c.value).join(", "); x.man=1; myfRefresh(curForm); });
/* ---- 내 서식 + 기존 입력 방식(질문·예시·자동 문장) 연결 ---- */
function myfLinkable(x){ return !!x.key && !(x.grid && x.grid.length===1 && (x.cols||[]).length>1); }
function myfStatusText(f,a){ const L=a.fields.filter(myfLinkable), rest=a.fields.length-L.length;
  return `‘${esc(a.name)}’ 서식으로 바뀌었어요. 칸 ${a.fields.length}개 중 ${L.length}개는 질문·예시로 자동 채워지고${rest?`, ${rest}개는 맨 아래 ‘내 서식에만 있는 칸’에 적어요`:""}.`; }
function myfExtraHTML(f,a){ const L=a.fields.filter(myfLinkable), only=a.fields.map((x,i)=>[x,i]).filter(([x])=>!myfLinkable(x)||x.grid);
  return `<div class="myf-extra"><div class="wiz-head"><b>내 서식에만 있는 칸</b><span>앱 질문과 연결되지 않은 칸이에요. 여기 적으면 내 서식에 그대로 들어가요.</span></div>
    ${only.length?only.map(([x,i])=>myfFieldHTML(x,i)).join(""):`<p class="hint">모든 칸이 위 입력과 연결됐어요.</p>`}
    ${L.length?`<details class="more"><summary>자동으로 연결된 칸 보기 (${L.length}개)</summary><div class="inner"><ul class="myf-map">${L.map(x=>`<li><b>${esc(x.label)}</b> ← ${esc((f.fields.find(y=>y.k===x.key)||{}).label||x.key)}</li>`).join("")}</ul></div></details>`:""}</div>`; }
function myfAutoSync(f,now){ const a=ATT[f.id]; if(!a) return; let R; try{ R=docVals(f,getF(f)); }catch(e){ return; }
  let ch=false; const V0=getF(f), raw=[...f.fields.map(y=>V0[y.k]||""), ...Object.values(V0._wz||{}).flat()].join(" ");
  a.fields.forEach(x=>{ if(x.check && !x.key && !x.man){ const t=raw.replace(/\s/g,""); const on=x.opts.filter(o=>{ const n=o.replace(/\s/g,""); return n.length>=2 && !/^기타/.test(n) && t.includes(n); }); const val=on.join(", "); if(val!==(x.value||"")){ x.value=val; ch=true; } return; } });
  a.fields.forEach(x=>{ if(!myfLinkable(x) || (x.grid && x.man)) return; let val=""; try{ val=fv(f,R.v,x.key)||""; }catch(e){}
    if(x.grid) val=val.split("\n").map(s=>s.replace(/^[○\-•]\s*/,"").trim()).filter(Boolean).join("\n");
    if(val){ if(x.value!==val){ x.value=val; ch=true; } x.auto=1; } else if(x.auto && x.value){ x.value=""; ch=true; } });
  if(now){ const el=document.getElementById("myf-pv"); if(el) el.innerHTML=myfPreview(a); myfSaveVals(f); }
  else myfRefresh(f); }
function renderMyForm(f){
  const a=ATT[f.id], n=a.fields.length, m=a.fields.filter(x=>(x.value||"").trim()).length;
  app.innerHTML=`<div class="fpage fade myf" style="--cc:var(--c-doc);--cc-soft:var(--c-doc-soft);--cc-deep:var(--c-doc-deep)">
    <div class="fbar"><button class="back b3d" type="button" data-goto="forms">← 서식함</button><h2>${f.em} ${esc(f.name)} <small class="ad-badge">내 서식</small></h2>
      <div class="fbar-btns"><button type="button" class="pill b3d main" id="myf-down">내 서식으로 받기</button><button type="button" class="pill b3d" id="myf-copy">복사</button><button type="button" class="pill b3d" id="myf-off">앱 기본 서식으로 돌아가기</button></div></div>
    <div class="ftabs" role="tablist"><button type="button" role="tab" class="on" data-ftab="in">✍️ 입력</button><button type="button" role="tab" data-ftab="pv">📄 내 서식 미리보기</button></div>
    <p class="status fstat" id="fstatus" role="status" aria-live="polite">‘${esc(a.name)}’ 서식으로 바꿨어요. 칸 ${n}개를 찾았고${m?` ${m}개는 앞에서 적은 내용으로 채웠어요`:""}. 왼쪽에 적으면 오른쪽 내 서식에 파란 글씨로 바로 들어가요.</p>
    <div class="fsplit">
      <section class="fin" id="fin" aria-label="입력">
        <div class="myf-note"><b>📎 ${esc(a.name)}</b><span>${a.mode==="same"?(a.ext==="docx"?"워드 서식 모양 그대로 채워져요.":"한글(.hwpx) 서식 모양 그대로 채워져요."):"PDF는 같은 항목 순서의 새 워드 서식으로 받아요."}</span></div>
        ${a.fields.map(myfFieldHTML).join("")}
        <details class="more myf-ai"><summary>✨ 메모로 AI에게 칸 채우기 부탁하기</summary><div class="inner">
          <div class="field"><label for="myf-memo">① 메모 (단어만 적어도 돼요)</label><textarea id="myf-memo" rows="3" placeholder="예: 3~12월 월 2회 나들이 19회, 4명 참여, 만족도 4명 중 3명 좋아요">${esc(a.memo||"")}</textarea></div>
          <div class="open-ai"><button type="button" class="ai-link b3d" data-myfai="gpt"><b>② 챗GPT</b><span>요청문 넣어 열기</span></button><button type="button" class="ai-link b3d" data-myfai="gem"><b>② 제미나이</b><span>복사 후 붙여 넣기</span></button><button type="button" class="ai-link b3d" data-myfai="cla"><b>② 클로드</b><span>요청문 넣어 열기</span></button></div>
          <p class="hint">AI가 1차 기획안을 보여 주면 확인한 뒤 ‘초안 작성’이라고 답하세요. 완성된 답을 통째로 복사해 아래에 붙여 넣으면 칸에 나눠 들어가요.</p>
          <div class="field"><label for="myf-paste">③ AI 답 붙여 넣기</label><textarea id="myf-paste" rows="4" placeholder="【칸 이름】 아래에 내용이 있는 답"></textarea></div>
          <div class="actions"><button type="button" class="btn b3d" id="myf-split">칸에 나눠 넣기</button></div></div></details>
      </section>
      <section class="fpv" id="fpv" aria-label="내 서식 미리보기"><div class="paper myf-paper" id="myf-pv">${myfPreview(a)}</div></section>
    </div></div>`;
}
/* 올린 서식 기억하기 (이 기기 브라우저에만) */
const MYF_KEY=id=>"aibox-myform-"+id;
async function myfSave(f,file){ try{ if(file.size>1500000) return; const buf=new Uint8Array(await file.arrayBuffer()); let bin=""; for(let i=0;i<buf.length;i+=0x8000) bin+=String.fromCharCode.apply(null,buf.subarray(i,i+0x8000));
  localStorage.setItem(MYF_KEY(f.id),JSON.stringify({name:file.name,type:file.type||"",b64:btoa(bin)})); }catch(e){} }
function myfSaveVals(f){ try{ const a=ATT[f.id]; if(!a) return; const raw=localStorage.getItem(MYF_KEY(f.id)); if(!raw) return; const o=JSON.parse(raw); o.vals=a.fields.map(x=>x.value||""); o.man=a.fields.map(x=>x.man?1:0); o.memo=a.memo||""; if(fvals[f.id]){ const c={}; Object.keys(fvals[f.id]).forEach(k=>{ if(k!=="_imgs") c[k]=fvals[f.id][k]; }); o.fv=c; } localStorage.setItem(MYF_KEY(f.id),JSON.stringify(o)); }catch(e){} }
function myfForget(f){ try{ localStorage.removeItem(MYF_KEY(f.id)); }catch(e){} }
const MYF_LOADING={};
async function myfRestore(f){ if(MYF_LOADING[f.id]) return; let o=null; try{ o=JSON.parse(localStorage.getItem(MYF_KEY(f.id))||"null"); }catch(e){} if(!o||!o.b64) return;
  MYF_LOADING[f.id]=1;
  try{ const bin=atob(o.b64), u=new Uint8Array(bin.length); for(let i=0;i<bin.length;i++) u[i]=bin.charCodeAt(i);
    const file=new File([u],o.name,{type:o.type}); const a=await parseTemplate(file); if(!a.fields||!a.fields.length) return;
    (o.vals||[]).forEach((v,i)=>{ if(a.fields[i] && v) a.fields[i].value=v; }); (o.man||[]).forEach((m,i)=>{ if(a.fields[i] && m) a.fields[i].man=1; }); a.memo=o.memo||"";
    if(o.fv && f.kind!=="aidoc"){ const v=getF(f); Object.keys(o.fv).forEach(k=>{ v[k]=o.fv[k]; }); }
    ATT[f.id]=a; if(curForm===f) renderForm(f);
  }catch(e){} finally{ delete MYF_LOADING[f.id]; } }
let myfTimer=null;
function myfRefresh(f){ clearTimeout(myfTimer); myfTimer=setTimeout(()=>{ const a=ATT[f.id], el=document.getElementById("myf-pv"); if(a&&el) el.innerHTML=myfPreview(a); myfSaveVals(f); },150); }
document.addEventListener("input",e=>{
  if(!curForm || !ATT[curForm.id]) return; const a=ATT[curForm.id];
  if(e.target.matches("[data-myf]")){ const x=a.fields[+e.target.dataset.myf]; if(x){ x.value=e.target.value; x.man=1; myfRefresh(curForm); } return; }
  if(e.target.id==="myf-memo"){ a.memo=e.target.value; myfSaveVals(curForm); return; }
});
document.addEventListener("click",e=>{
  if(!curForm || !ATT[curForm.id] || !document.getElementById("myf-pv")) return;
  const f=curForm, a=ATT[f.id], st=document.getElementById("fstatus");
  if(e.target.closest("#myf-off")){ delete ATT[f.id]; myfForget(f); renderForm(f); return; }
  if(e.target.closest("#myf-down")){ const keep=up; const base=a.name.replace(/\.[^.]+$/,"").replace(/[\\/:*?"<>|]/g,"").trim();
    (async()=>{ try{ up=a; if(a.mode==="same"){ const blob=await buildFilled(); await saveFile(`${base}_작성.${a.ext}`, blob, st); } else await saveFile(`${base}_작성.docx`, upNewDocx(), st); }
      catch(err){ if(st){ st.textContent="내 서식으로 만들지 못했어요. ‘앱 기본 서식으로 돌아가기’ 후 워드 받기를 이용해 주세요."; st.classList.add("warn"); } } finally{ up=keep; } })(); return; }
  if(e.target.closest("#myf-copy")){ const t=a.fields.map(x=>`${x.label}\n${(x.value||"").trim()||"-"}`).join("\n\n"); copyText(t,null,()=>{ st.classList.remove("warn"); st.textContent="칸 이름과 내용을 복사했어요."; },()=>{ st.classList.add("warn"); st.textContent="자동 복사가 막혀 있어요."; }); return; }
  const ai=e.target.closest("[data-myfai]"); if(ai){ const text=myfPrompt(f,a); copyText(text,null,()=>{},()=>{});
    const url={gpt:"https://chatgpt.com/#disable_auto_send=1&q="+encodeURIComponent(text),cla:"https://claude.ai/new?q="+encodeURIComponent(text),gem:"https://gemini.google.com/app"}[ai.dataset.myfai];
    window.open(url,"_blank","noopener"); st.classList.remove("warn"); st.textContent=ai.dataset.myfai==="gem"?"요청문을 복사했어요. 열린 제미나이 창에 붙여 넣으세요.":"요청문을 넣어 AI 창을 열었어요. 기획안을 확인하고 ‘초안 작성’이라고 답하세요."; return; }
  if(e.target.closest("#myf-split")){ const t=(document.getElementById("myf-paste").value||""); const re=/【([^】]+)】/g; let mm, marks=[]; while((mm=re.exec(t))) marks.push({l:mm[1].trim(),s:mm.index,e:re.lastIndex});
    let n=0; const nz=s=>s.replace(/\s|\(.*?\)/g,"");
    marks.forEach((mk,i)=>{ const seg=t.slice(mk.e, i+1<marks.length?marks[i+1].s:t.length).replace(/^\s*\(표[^)]*\)\s*/,"").trim(); const x=a.fields.find(y=>nz(y.label)===nz(mk.l)); if(x&&seg){ x.value=seg; n++; } });
    renderMyForm(f); myfSaveVals(f); const s2=document.getElementById("fstatus"); if(s2){ s2.classList.toggle("warn",!n); s2.textContent= n?`AI 답을 ${n}개 칸에 나눠 넣었어요. 오른쪽 내 서식에서 확인하세요.`:"【칸 이름】 표시가 있는 답을 찾지 못했어요. AI 답을 통째로 붙여 넣었는지 확인해 주세요."; } return; }
  const mic=e.target.closest("[data-myfmic]"); if(mic){ const i=+mic.dataset.myfmic, el=document.getElementById("myf-"+i); startMic(mic, el, t=>{ el.value=(el.value?el.value+" ":"")+t; a.fields[i].value=el.value; myfRefresh(f); }); return; }
});

let exTimer=null;
function syncFields(f){ const v=getF(f); f.fields.forEach(x=>{ const el=document.getElementById(`ff-${f.id}-${x.k}`); if(el && document.activeElement!==el && el.value!==(v[x.k]||"")){ el.value=v[x.k]||""; if(el.tagName==="TEXTAREA") el.rows=Math.min(9,Math.max(3,(el.value).split("\n").length)); } }); }

/* ---- 메모·회의 사진 (AI에게 함께 보내기) ---- */
function mimgList(list,pre){ return list.map((m,i)=>`<figure><img src="${m.thumb}" alt="메모 사진 ${i+1}"><button type="button" data-mimg-del="${pre}:${i}" aria-label="사진 ${i+1} 빼기">빼기</button></figure>`).join(""); }
function mimgHTML(list,pre){ return `<div class="mimg"><div class="mimg-top"><label class="pill b3d" for="${pre}-img">${ico("up")}메모·회의 사진 올리기</label><input type="file" id="${pre}-img" class="sr-file" accept="image/*" multiple><span class="mimg-n">${list.length?`${list.length}장 올림`:"손글씨 메모, 화이트보드, 회의 메모 사진 (최대 5장)"}</span></div>
  <div class="mimg-list" id="${pre}-imgs">${mimgList(list,pre)}</div>
  <p class="mimg-warn">사진에 이름·주민번호·연락처가 보이면 가리고 찍어주세요. 사진은 이 기기에서만 보여요. 챗GPT 창에서는 <b>+ 버튼으로 같은 사진을 직접 붙여야</b> 해요.</p></div>`; }
const imgPromptLine = n => n ? `첨부한 사진 ${n}장은 손으로 쓴 메모(회의 메모 포함)야. 먼저 사진 속 글을 꼼꼼히 읽고, 그 내용을 바탕으로 각 칸을 채워줘. 알아보기 어려운 글자나 숫자는 추측하지 말고 [확인 필요]라고 써줘.\n\n` : "";
async function addMemoImgs(files,list){ const room=5-list.length; for(const file of Array.from(files).slice(0,Math.max(0,room))){ try{ const r=await readRefImage(file); list.push({name:file.name,thumb:r.thumb}); }catch(e){} } }
function mimgRefresh(list,pre){ const box=document.getElementById(pre+"-imgs"); if(box) box.innerHTML=mimgList(list,pre); const n=box&&box.closest(".mimg").querySelector(".mimg-n"); if(n) n.textContent=list.length?`${list.length}장 올림`:"손글씨 메모, 화이트보드, 회의 메모 사진 (최대 5장)"; }

function renderPend(){
  const el=document.getElementById("up-work"); if(!el) return;
  el.innerHTML=`<section class="card pend"><h3 class="step-title"><b>2</b>이 메모로 어떤 서류를 만들까요?</h3>
    <p class="hint">앱은 손글씨를 직접 읽지 못해서 어떤 메모인지 알 수 없어요. 만들 서류를 골라주시면 그 작성 화면에 사진을 붙여서 열어 드려요.</p>
    ${mimgHTML(pendImgs,"pend")}
    <div class="pend-grid">${[...FORMS,...myForms()].map(f=>`<button type="button" class="pend-btn${f.id==="hoeui"?" pri":""}" data-photo-form="${f.id}"><b>${esc(f.name)}</b><span>${esc(f.desc)}</span></button>`).join("")}<button type="button" class="pend-btn new" data-goto="make"><b>+ 여기에 없는 서식</b><span>방문대장·예산 공개 등 직접 만들기</span></button></div>
    <p class="hint">우리 시설에서 쓰는 다른 서식에 채우려면 위 <b>서식 파일 고르기</b>로 워드·한글 서식을 올리세요. 올린 사진은 그대로 이어서 써요.</p></section>`;
}
/* ================= 새 서식 만들기 (목록에 없는 서식) ================= */
const PRESETS=[
 {name:"방문대장",kind:"ledger",cols:["방문 일시","방문자 성명","소속·관계","방문 목적","연락처","확인"],blank:15,meta:"기간"},
 {name:"물품 관리 대장",kind:"ledger",cols:["번호","품명","규격","수량","구입일","보관 장소","비고"],blank:15,meta:"기간"},
 {name:"후원물품 접수 대장",kind:"ledger",cols:["접수일","후원자(단체)","품목","수량","사용처","확인"],blank:15,meta:"기간"},
 {name:"차량 운행일지",kind:"ledger",cols:["운행일","운행자","출발지","목적지","출발 km","도착 km","운행 목적"],blank:15,meta:"기간"},
 {name:"예산 공개",kind:"ledger",cols:["구분(세입·세출)","관·항·목","예산액(원)","비고"],blank:12,meta:"회계연도"},
 {name:"결산 공개",kind:"ledger",cols:["구분(세입·세출)","관·항·목","예산액(원)","결산액(원)","비고"],blank:12,meta:"회계연도"},
 {name:"안전 점검표",kind:"ledger",cols:["점검 항목","양호","불량","조치 사항"],rows:["소화기 위치·압력","비상구·대피로","가스 밸브·경보기","전기 콘센트·멀티탭","화재감지기 작동","구급함 약품 기한"],blank:4,meta:"점검일"},
 {name:"외출·외박 신청서",kind:"form",labels:["대상","구분 (외출·외박)","기간","행선지","동행자","비상 연락처","귀가 예정 시간","신청 사유","신청일","확인자"]},
 {name:"상담일지",kind:"form",labels:["일시","대상","상담자","상담 방법","상담 내용","조치 및 계획","작성자"]},
 {name:"직원 교육일지",kind:"form",labels:["교육명","일시","장소","강사","참석자","교육 내용","적용 계획","작성자"]},
 {name:"자원봉사 활동 확인서",kind:"form",labels:["성명","소속","활동 일시","활동 시간","활동 내용","확인자"]},
 {name:"사고 보고서",kind:"form",labels:["발생 일시","발생 장소","대상","사고 경위 (사실)","조치 내용","보호자 연락","재발 방지 대책","작성자"]}
];
const AREA_RE=/내용|경위|계획|사유|사항|대책|소감|의견|목적|결과|평가|비고란/;
function labelKey(l,i){ const n=l.replace(/\s|\([^)]*\)/g,""); if(/^(기관명|시설명|센터명)$/.test(n)) return "org"; if(/^(작성자|기록자)$/.test(n)) return "writer"; if(/^(신청일|작성일|작성일자|일자|보고일)$/.test(n)) return "date"; return "c"+i; }
function makeFormObj(d){
  if(d.kind==="ledger"){
    return {id:d.id, my:1, name:d.name, desc:`대장형 표 · ${d.cols.length}칸`, kind:"ledger", cols:d.cols,
      fields:[{k:"title",label:"서식 제목",short:1,def:d.name},{k:"meta",label:d.meta||"기간",short:1,ph:d.meta==="회계연도"?"예: 2026년":"예: 2026. 10. ~ 12."},{k:"org",label:"시설명",short:1},{k:"blank",label:"빈 줄 수 (손으로 쓸 줄)",short:1,def:String(d.blank??15)},
        {k:"rows",label:"기록 (한 줄에 한 건)",type:"area",def:(d.rows||[]).join("\n"),ph:`칸 사이는 띄어쓰기 / 띄어쓰기로 구분해요.\n예: ${d.cols.map(c=>"○○").join(" / ")}`}]};
  }
  const used=new Set(), fields=d.labels.map((l,i)=>{ let k=labelKey(l,i); if(used.has(k)) k="c"+i; used.add(k); return k==="date"?{k,label:l,type:"date",def:"today",short:1}:{k,label:l,...(AREA_RE.test(l)?{type:"area"}:{short:1})}; });
  if(!used.has("org")) fields.push({k:"org",label:"시설명",short:1});
  return {id:d.id, my:1, name:d.name, desc:`직접 만든 서식 · ${d.labels.length}칸`, kind:"generic", fields};
}
let MYFORMS=(()=>{ try{ return JSON.parse(localStorage.getItem("aibox-myforms")||"[]"); }catch(e){ return []; } })();
const saveMy=()=>{ try{ localStorage.setItem("aibox-myforms",JSON.stringify(MYFORMS)); }catch(e){} };
const myForms=()=>MYFORMS.map(d=>FBY[d.id]).filter(Boolean);
MYFORMS.forEach(d=>{ FBY[d.id]=makeFormObj(d); });
const mk={name:"",kind:"form",labels:"",blank:15,meta:"기간",rows:"",touched:false,preset:null};
function mkFromPreset(p){ mk.name=p.name; mk.kind=p.kind; mk.labels=(p.kind==="ledger"?p.cols:p.labels).join("\n"); mk.blank=p.blank??15; mk.meta=p.meta||"기간"; mk.rows=(p.rows||[]).join("\n"); mk.preset=p.name; mk.touched=false; }
function mkGuess(name){ const n=name.replace(/\s/g,""); const p=PRESETS.find(x=>{ const pn=x.name.replace(/\s|·/g,""); return n && (pn.includes(n.replace(/·/g,""))||n.replace(/·/g,"").includes(pn)); }); return p; }
function mkDef(){ const labels=mk.labels.split("\n").map(s=>s.trim()).filter(Boolean); return mk.kind==="ledger"?{name:mk.name.trim()||"새 서식",kind:"ledger",cols:labels,blank:mk.blank,meta:mk.meta,rows:mk.rows.split("\n").filter(s=>s.trim())}:{name:mk.name.trim()||"새 서식",kind:"form",labels}; }
function mkPrompt(){ return `그룹홈(장애인복지관)에서 쓰는 '${mk.name.trim()||"[서식 이름]"}' 서식을 만들려고 해.\n${mk.kind==="ledger"?"표(대장) 형식이야. 표 맨 윗줄에 들어갈 열 이름을":"신청서·일지처럼 칸을 채우는 형식이야. 들어갈 항목 이름을"} 한 줄에 하나씩, 10개 이내로 써줘.\n항목 이름만 쓰고 번호, 설명, 기호는 붙이지 마.\n이용자 주민번호, 진단명 같은 민감한 정보 칸은 넣지 마.`; }
function mkPreview(){ const d=mkDef(); if(!(d.cols||d.labels).length) return `<p class="empty">항목을 한 줄에 하나씩 적으면 여기에 서식 모양이 보여요.</p>`; const f=makeFormObj({...d,id:"_pv"}); const v={}; f.fields.forEach(x=>v[x.k]=x.def==="today"?todayISO():(profFill()[x.k]||x.def||"")); if(f.kind==="ledger") v.blank=String(Math.min(+mk.blank||0,6)); return blocksHTML(docBlocks(f,v))+(f.kind==="ledger"&&+mk.blank>6?`<p class="hint">미리보기는 빈 줄 6개까지만 보여요. 받을 때는 ${+mk.blank}줄이에요.</p>`:""); }
function renderMake(){
  app.innerHTML=`<div class="fpage fade">
    <div class="fbar"><button class="back b3d" type="button" data-goto="forms">← 서식함</button><h2>새 서식 만들기</h2>
      <div class="fbar-btns"><button type="button" class="pill b3d main" id="mk-go">이 서식으로 작성하기</button></div></div>
    <p class="fstat" id="mk-status">${mk.toDonate?"후원 관리 목록에 추가할 서식을 만들어요. 만든 서식은 후원 서식 목록에 들어가요.":pendImgs.length?`메모 사진 ${pendImgs.length}장을 이어서 쓸게요. 서식을 만들면 작성 화면에 붙여 드려요.`:"목록에 없는 서식을 이름과 항목만 정하면 바로 만들어 써요. 만든 서식은 서식함에 저장돼요."}</p>
    <div class="fsplit mk">
      <section class="fin">
        <div class="field"><label for="mk-name">① 서식 이름</label><input id="mk-name" type="text" placeholder="예: 방문대장, 예산 공개, 외출·외박 신청서" value="${esc(mk.name)}"></div>
        <div class="mk-chips"><span>자주 쓰는 서식</span>${PRESETS.map((p,i)=>`<button type="button" class="mk-chip${mk.preset===p.name?" on":""}" data-preset="${i}">${p.name}</button>`).join("")}</div>
        <fieldset class="mk-kind"><legend>② 서식 모양</legend>
          <label><input type="radio" name="mk-kind" value="form" ${mk.kind==="form"?"checked":""}><span><b>칸 채우기형</b><small>신청서·일지·보고서</small></span></label>
          <label><input type="radio" name="mk-kind" value="ledger" ${mk.kind==="ledger"?"checked":""}><span><b>대장형 표</b><small>방문대장·물품대장·예산 공개</small></span></label></fieldset>
        <div class="field"><label for="mk-labels">③ ${mk.kind==="ledger"?"표 맨 윗줄 (열 이름)":"항목"} <small>한 줄에 하나씩</small></label><textarea id="mk-labels" rows="7">${esc(mk.labels)}</textarea></div>
        ${mk.kind==="ledger"?`<div class="fgrid"><div class="field"><label for="mk-meta">위쪽 정보 칸</label><input id="mk-meta" type="text" value="${esc(mk.meta)}" placeholder="예: 기간, 회계연도, 점검일"></div><div class="field"><label for="mk-blank">빈 줄 수</label><input id="mk-blank" type="number" min="0" max="40" value="${esc(String(mk.blank))}"></div></div>`:""}
        <div class="mk-ai"><b>항목이 떠오르지 않으면</b><a class="ai-link b3d" id="mk-gpt" href="https://chatgpt.com/#disable_auto_send=1&q=${encodeURIComponent(mkPrompt())}" target="_blank" rel="noopener"><b>챗GPT에게 항목 추천받기</b><span>답을 ③에 붙여 넣으세요</span></a></div>
      </section>
      <section class="fpv"><div class="paper" id="mk-pv">${mkPreview()}</div></section>
    </div></div>`;
}
function mkRefresh(){ const pv=document.getElementById("mk-pv"); if(pv) pv.innerHTML=mkPreview(); const a=document.getElementById("mk-gpt"); if(a) a.href="https://chatgpt.com/#disable_auto_send=1&q="+encodeURIComponent(mkPrompt()); }
function mkCreate(){
  const d=mkDef(), st=document.getElementById("mk-status");
  if(!(d.cols||d.labels).length){ st.textContent="③에 항목을 한 줄에 하나씩 적어주세요."; st.classList.add("warn"); return; }
  const old=MYFORMS.findIndex(x=>x.name===d.name); d.id= old>=0?MYFORMS[old].id:"my"+Date.now().toString(36);
  if(old>=0) MYFORMS[old]=d; else MYFORMS.push(d); saveMy();
  FBY[d.id]=makeFormObj(d); delete fvals[d.id];
  const f=FBY[d.id]; if(pendImgs.length){ getF(f)._imgs=pendImgs.splice(0); openAIOnRender=true; }
  if(mk.toDonate){ DNL.add=[...new Set([...(DNL.add||[]),d.id])]; saveDNL(); }
  Object.assign(mk,{name:"",kind:"form",labels:"",blank:15,meta:"기간",rows:"",touched:false,preset:null,toDonate:false});
  location.hash="form-"+d.id;
}
function myFormsHTML(){ const L=myForms(); if(!L.length) return ""; return `<h3 class="sub-title">내가 만든 서식</h3><div class="my-list">${L.map(f=>`<div class="my-row"><button type="button" class="my-open" data-form="${f.id}"><b>${esc(f.name)}</b><span>${esc(f.desc)}</span></button><button type="button" class="my-del" data-myform-del="${f.id}">삭제</button></div>`).join("")}</div>`; }

/* ================= 후원 관리 ================= */
const DN_FORMS=[
 {id:"dn-money",name:"후원금·후원품 대장",kind:"ledger",cols:["일자","후원자","받은 금액(원)","후원품","사용 내역","비고"],blank:15,meta:"기간"},
 {id:"dn-goods",name:"후원물품 접수·사용 대장",kind:"ledger",cols:["접수일","후원자(단체)","품목","수량","사용처","사용일","확인"],blank:15,meta:"기간"},
 {id:"dn-receipt",name:"기부금 영수증 발급 대장",kind:"ledger",cols:["발급일","후원자","후원 기간","금액(원)","영수증 번호","발급 방법","비고"],blank:15,meta:"연도"},
 {id:"dn-card",name:"후원자 관리 카드",kind:"form",labels:["후원자","구분 (개인·단체)","연락처","후원 시작일","후원 방법 (정기·일시·물품)","후원 내용","감사 연락 기록","비고","작성자"]},
 {id:"dn-report",name:"후원금 사용 결과 보고",kind:"form",labels:["보고 기간","받은 후원금 합계","사용 내역","남은 금액","후원으로 달라진 일상","감사 인사","작성자"]}
];
DN_FORMS.forEach(d=>{ FBY[d.id]=makeFormObj(d); FBY[d.id].desc=d.kind==="ledger"?"대장형 표":"칸 채우기형"; });
let DNL=(()=>{ try{ return JSON.parse(localStorage.getItem("aibox-dnlist")||"{}"); }catch(e){ return {}; } })();
const saveDNL=()=>{ try{ localStorage.setItem("aibox-dnlist",JSON.stringify(DNL)); }catch(e){} };
function dnList(){ const hide=new Set(DNL.hide||[]); return [...DN_FORMS.filter(d=>!hide.has(d.id)).map(d=>FBY[d.id]),...(DNL.add||[]).map(id=>FBY[id]).filter(Boolean)]; }
const ghDonModes=[
 ["thanks","감사 인사","후원을 받았을 때",["gift","program","next"]],
 ["checkin","안부 문자","후원자께 부담 없이 소식을 전할 때",["program","result","next"]],
 ["funds","후원금·물품 사용 안내","무엇에 사용했는지 알릴 때",["period","gift","used","next"]],
 ["result","활동·사업 성과 공유","확인된 활동과 결과를 전할 때",["period","program","result","next"]],
 ["growth","아동 성장 소식","개인을 특정하지 않고 변화를 전할 때",["period","program","growth","next"]]
];
const ghDonFields={
 recipient:["받는 분","예: 후원자님 / ○○기업 담당자님"],
 gift:["후원 내용","예: 미술 재료 / 확인된 후원금액"],
 period:["기간","예: 11월 활동 기간"],
 program:["사업·활동","예: 아동 미술 프로그램"],
 used:["실제 사용 내역","예: 수업에 사용한 미술 재료 구입"],
 result:["확인된 결과","예: 참석 인원 또는 실제 진행한 활동"],
 growth:["관찰한 변화","예: 재료를 직접 골라 작품을 완성하는 모습"],
 next:["마무리 한마디","예: 앞으로도 활동 소식을 나누겠습니다."]
};
let ghDonType="thanks",ghDonDrafts=Object.create(null);
function ghDonMessage(mode,v){
 const val=k=>String(v[k]||"").trim(), donor=val("recipient")||"후원자님";
 const body=[donor+", 안녕하세요. 용인시기흥장애인복지관입니다."];
 const add=(label,k)=>{if(val(k))body.push(label+": "+val(k));};
 if(mode==="thanks"){body.push("따뜻한 마음을 보내 주셔서 감사합니다.");add("후원 내용","gift");add("관련 활동","program");}
 if(mode==="checkin"){body.push("그동안 잘 지내셨는지요? 복지관 소식을 전해 드립니다.");add("최근 활동","program");add("활동 소식","result");}
 if(mode==="funds"){body.push("보내 주신 후원의 사용 내역을 안내드립니다.");add("사용 기간","period");add("후원 내용","gift");add("확인된 사용 내역","used");}
 if(mode==="result"){body.push("후원과 관련한 복지관 활동 소식을 전해 드립니다.");add("활동 기간","period");add("사업·활동","program");add("확인된 결과","result");}
 if(mode==="growth"){body.push("아동 프로그램의 활동 소식을 전해 드립니다.");add("활동 기간","period");add("프로그램","program");if(v.consent)add("활동 중 관찰한 변화","growth");}
 body.push(val("next")||"함께해 주셔서 고맙습니다.");
 return body.join("\n\n");
}
function renderDonate(){
  const mode=ghDonModes.find(m=>m[0]===ghDonType)||ghDonModes[0];
  const d=ghDonDrafts[mode[0]]||(ghDonDrafts[mode[0]]=Object.create(null));
  const req={funds:"used",result:"result",growth:"program"}[mode[0]];
  app.innerHTML=`<div class="ghome dn fade">
    <div class="dn-head"><h2>후원자 소통·성과 공유</h2><p>상황을 골라 확인된 내용만 적으면 후원자에게 전할 문장이 완성됩니다.</p></div>
    <nav class="dn-msgs" aria-label="후원 메시지 유형">${ghDonModes.map(([id,t,h])=>`<button class="qm" type="button" data-gh-donor-mode="${id}" aria-pressed="${id===mode[0]}" style="${id===mode[0]?'border-color:#287351;background:#eaf7ef':''}">${ico("mail")}<b>${esc(t)}</b><span>${esc(h)}</span></button>`).join("")}</nav>
    <div class="gcols" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr))">
      <section class="gbox dn-board"><div class="gbox-h"><h2>보낼 내용</h2></div>
        ${["recipient",...mode[3]].map(k=>`<label class="field" style="display:block;margin:0 0 9px"><b>${esc(ghDonFields[k][0])}</b><input style="display:block;box-sizing:border-box;width:100%" type="text" data-gh-donor-field="${k}" placeholder="${esc(ghDonFields[k][1])}" value="${esc(d[k]||"")}"></label>`).join("")}
        ${mode[0]==="growth"?`<p class="dn-note">이름·사진·학교·진단명 등 식별 정보는 적지 마세요. 당사자와 필요한 경우 보호자의 공유 동의 및 기관 기준이 확인되지 않으면 개별 변화는 보내지 않습니다.</p><label style="display:block;margin-top:5px"><input type="checkbox" id="gh-donor-consent"${d.consent?" checked":""}> 공유 범위를 확인했고, 개인을 특정할 수 없는 문장입니다.</label>`:`<p class="dn-note">금액·일정·인원은 확인된 사실만 입력하고, 개인정보는 빼 주세요.</p>`}
      </section>
      <section class="gbox dn-board"><div class="gbox-h"><h2>${esc(mode[1])} 예시</h2><button type="button" class="bd-btn pri" id="gh-donor-copy">복사</button></div>
        <textarea class="paper" id="gh-donor-preview" aria-label="보낼 문장 미리보기" readonly rows="13" style="box-sizing:border-box;width:100%;resize:vertical;line-height:1.65"></textarea>
        <p class="dn-note" id="gh-donor-status" role="status"></p>
      </section>
    </div></div>`;
  const area=document.getElementById("gh-donor-preview"), st=document.getElementById("gh-donor-status"), copy=document.getElementById("gh-donor-copy"), cond=document.getElementById("gh-donor-consent");
  function paint(){
    area.value=ghDonMessage(mode[0],d);
    copy.disabled=!!(req&&!String(d[req]||"").trim());
    st.textContent=copy.disabled?ghDonFields[req][0]+"을 먼저 적어 주세요.":mode[0]==="growth"&&!d.consent?"공유 범위가 확인되기 전에는 관찰한 변화가 문장에 들어가지 않습니다.":"내용을 확인하고 복사해 문자·메일 등에 붙여 넣으세요.";
  }
  app.querySelectorAll("[data-gh-donor-mode]").forEach(b=>b.addEventListener("click",()=>{
    ghDonType=b.dataset.ghDonorMode;renderDonate();
    app.querySelector('[data-gh-donor-mode="'+ghDonType+'"]').focus({preventScroll:true});
  }));
  app.querySelectorAll("[data-gh-donor-field]").forEach(a=>a.addEventListener("input",()=>{d[a.dataset.ghDonorField]=a.value;paint();}));
  if(cond)cond.addEventListener("change",()=>{d.consent=cond.checked;paint();});
  copy.addEventListener("click",()=>copyText(area.value,area,()=>{st.textContent="복사했어요."},()=>{st.textContent="자동 복사가 되지 않았어요. 선택된 문장을 직접 복사해 주세요."}));
  paint();
}


/* ---- 서식 항목 더하기·빼기 (기기에 저장) ---- */
let FCUST=(()=>{ try{ return JSON.parse(localStorage.getItem("aibox-fcustom")||"{}"); }catch(e){ return {}; } })();
const saveFC=()=>{ try{ localStorage.setItem("aibox-fcustom",JSON.stringify(FCUST)); }catch(e){} };
function applyCustom(f){
  if(!f._base){ f._base=f.fields.slice(); if(f.cols) f._baseCols=f.cols.slice(); }
  const c=FCUST[f.id]||{};
  f._hide=new Set(c.hide||[]);
  f.fields=f._base.filter(x=>!f._hide.has(x.k)).concat((c.extra||[]).map(e=>({k:e.k,label:e.label,extra:1,...(e.type==="area"?{type:"area"}:{short:1})})));
  if(f._baseCols) f.cols=f._baseCols.filter(x=>!(c.hideCols||[]).includes(x)).concat(c.extraCols||[]);
}
function customHTML(f){
  const c=FCUST[f.id]||{}, led=f.kind==="ledger";
  const hiddenF=f._base.filter(x=>f._hide.has(x.k));
  const hidCols=led?(c.hideCols||[]):[];
  return `<div class="f-cust">
    <div class="f-addbox f-delbox"><label for="fdel-sel">− ${led?"빼고 싶은 열":"빼고 싶은 항목"}</label>
      <div class="f-add"><select id="fdel-sel"><option value="">${led?"뺄 열을 고르세요":"뺄 항목을 고르세요"}</option>${led?f.cols.map(col=>`<option value="${esc(col)}">${esc(col)}</option>`).join(""):f.fields.map(x=>`<option value="${x.k}">${esc(x.label)}</option>`).join("")}</select><button type="button" class="pill b3d" id="fdel-btn">빼기</button></div></div>
    <div class="f-addbox"><label for="fadd-name">+ ${led?"추가하고 싶은 열":"추가하고 싶은 항목"}</label>
      <div class="f-add"><input id="fadd-name" type="text" placeholder="${led?"예: 비고, 담당자 (여러 개는 쉼표로)":"예: 준비물, 협력 기관 (여러 개는 쉼표로)"}">${led?"":`<select id="fadd-type" aria-label="칸 크기"><option value="short">짧은 칸</option><option value="area">긴 칸</option></select>`}<button type="button" class="pill b3d" id="fadd-btn">추가</button></div></div>
    ${hiddenF.length||hidCols.length?`<div class="f-hidden"><span>뺀 ${led&&!hiddenF.length?"열":"항목"}</span>${hiddenF.map(x=>`<button type="button" data-frestore="${x.k}">${esc(x.label)} 다시 넣기</button>`).join("")}${hidCols.map(col=>`<button type="button" data-fcolrestore="${esc(col)}">${esc(col)} 다시 넣기</button>`).join("")}</div>`:""}
    ${FCUST[f.id]?`<button type="button" class="f-reset" id="freset">처음 서식으로 되돌리기</button>`:""}
  </div>`;
}
