function ghServiceSource(g,p){
 if(/접수면접|치료재활진단|언어치료|운동치료|작업치료|인지학습치료|음악치료|미술치료|수중재활/.test(p))return "https://www.a-sak.or.kr/services/programs.php";
 if(/무료법률상담|아삭공모전|이용자권리교육/.test(p))return "https://www.a-sak.or.kr/services/programs5.php";
 if(p==="하이드림솔루션")return "https://www.a-sak.or.kr/services/hidream.php";
 if(p==="주간이용센터")return "https://www.a-sak.or.kr/services/programs3.php";
 return g.url;
}
const GH_SECTOR_STATE={promo:{g:0,p:0,channel:null},msg:{g:0,p:0},life:{g:0,p:0}};
const GH_PROMO_CHANNELS=BY["sns-post"].chips.find(x=>x.k==="where").opts;
const GH_PROMO_SNS="인스타그램·블로그·카카오톡";
function ghPromoChannel(currentWhere){
 const channel=GH_SECTOR_STATE.promo.channel||currentWhere||GH_PROMO_CHANNELS[0];
 return '<fieldset class="gh-promo-channel"><legend>어디에 올리나요?</legend><div class="chips">'+GH_PROMO_CHANNELS.map(x=>'<button type="button" class="pill b3d'+(channel===x?' main':'')+'" data-gh-promo-channel="'+esc(x)+'" aria-pressed="'+(channel===x)+'">'+esc(x)+'</button>').join('')+'</div><p class="hint">채널을 고르면 해당 채널 원고가 열리고, 아래에서 원하는 홍보물 유형을 바꿀 수 있어요.</p></fieldset>';
}
function ghFieldScenarios(c){
 const i={promo:0,msg:1,life:2}[c],g=GH_SECTOR_STATE[c].g;
 const sector=options.catalog[g],program=sector.items[GH_SECTOR_STATE[c].p],specific=GH_PROGRAM_WORK.find(x=>x[0].test(program));
 return (specific?specific[i+1]:[]).concat(GH_FIELD_WORK[g]?.[i]||[]);
}
function ghScenarios(c){
 const common=GH_COMMON_WORK[c],fields=c==="msg"&&!GH_SECTOR_STATE[c].programOn?[]:ghFieldScenarios(c);
 return Array.from(new Set(c==="msg"?common.concat(fields):fields.concat(common)));
}
function ghSmsDistrict(part){
 const st=GH_SECTOR_STATE.msg,g=options.catalog[st.g];
 const chips=(list)=>'<div class="gh-scenario-grid">'+list.map(x=>'<button class="b3d" type="button" data-gh-scenario="msg:'+ghScenarios("msg").indexOf(x)+'" aria-pressed="'+(st.picked===x)+'">'+esc(x)+'</button>').join('')+'</div>';
 return part!=="program"?'<section class="gh-work-sector gh-sms-choices"><h3>어떤 문자를 보내나요?</h3>'+chips(GH_COMMON_WORK.msg)+'</section>':
  '<details class="gh-sms-program"'+(st.programOn?' open':'')+'><summary>특정 사업·프로그램 문자'+(st.programOn?' · '+esc(g.items[st.p]):'')+'</summary>'+
  '<div class="gh-sector-program"><label for="gh-sms-area">사업 분야</label><select id="gh-sms-area" data-gh-sector="msg">'+options.catalog.map((z,i)=>'<option value="'+i+'"'+(i===st.g?' selected':'')+'>'+esc(z.label)+'</option>').join('')+'</select>'+
  '<label for="gh-sector-program">프로그램</label><select id="gh-sector-program" data-gh-program="msg"><option value="-1"'+(!st.programOn?' selected':'')+'>선택 안 함</option>'+g.items.map((p,i)=>'<option value="'+i+'"'+(st.programOn&&i===st.p?' selected':'')+'>'+esc(p)+'</option>').join('')+'</select></div>'+
  (st.programOn?'<h3>이 사업에서 자주 보내는 문자</h3>'+chips(ghFieldScenarios("msg")):'')+'</details>';
}
function ghDefaultScenario(c){
 const list=ghScenarios(c),saved=GH_SECTOR_STATE[c].picked;
 const ix=list.indexOf(saved||({msg:"참여 안내",promo:GH_PROMO_SNS}[c]));
 return ix<0?0:ix;
}
function ghDistrict(c){
 if(c==="msg")return ghSmsDistrict();
 const s=GH_SECTOR_STATE[c],g=options.catalog[s.g],ps=g.items;
 return '<section class="gh-work-sector"><fieldset><legend>1. 복지관 사업 분야</legend><div class="chips">'+options.catalog.map((x,i)=>'<label class="chip"><input type="radio" name="gh-sector" data-gh-sector="'+c+'" value="'+i+'"'+(s.g===i?' checked':'')+'><span>'+esc(x.label)+'</span></label>').join('')+'</div></fieldset>'+
  '<div class="gh-sector-program"><label for="gh-sector-program">2. 실제 사업·프로그램</label><select id="gh-sector-program" data-gh-program="'+c+'">'+ps.map((x,i)=>'<option value="'+i+'"'+(s.p===i?' selected':'')+'>'+esc(x)+'</option>').join('')+'</select><a href="'+esc(ghServiceSource(g,ps[s.p]))+'" target="_blank" rel="noopener">공식 사업소개 ↗</a></div>'+
  '<h3>3. '+esc(ps[s.p])+'에서 어떤 일을 하나요?</h3><div class="gh-scenario-grid">'+ghScenarios(c).map((x,i)=>'<button class="b3d" type="button" data-gh-scenario="'+c+':'+i+'" aria-pressed="'+(s.picked===x)+'">'+esc(x)+'</button>').join('')+'</div>'+
  '<p class="hint">사업명은 복지관 공식 안내 기준입니다. 아래 선택지는 업무 예시이며 실제 모집 일정은 아닙니다.</p></section>';
}
function ghOpenScenario(c,i){
 const q=GH_SECTOR_STATE[c],g=options.catalog[q.g],program=c==="msg"&&!q.programOn?"":g.items[q.p],what=ghScenarios(c)[i],ctx={program,what,group:g.label,check:g.check,area:g.area};
 if(!what)return;
 q.picked=what;
 if(c==="life"){options.plan(ctx);return;}
 const k=c==="msg"?"gh-welfare-msg":/카드뉴스/.test(what)?"cardnews":/포스터/.test(what)?"poster":/삽화/.test(what)?"image-prompt":/인포그래픽/.test(what)?"infographic":/소식지/.test(what)?"newsletter":/후기|인스타그램/.test(what)?"sns-post":"notice";
 const t=BY[k],key=k+"|"+g.label+"|"+program+"|"+what;
 if(!ghScenarioDrafts[key]){
   const active=ghScenarioRoute,live=values[k];ghScenarioRoute=null;delete values[k];const fresh=getVals(t);ghScenarioRoute=active;if(live)values[k]=live;else delete values[k];
   fresh.v._work=ctx;
   if(c==="msg")fresh.v.reader=(q.programOn&&(q.g===1||q.g===4))?"보호자·가족":q.programOn&&q.g===9?"후원자·봉사자":"이용자";
   if(k==="notice")fresh.v.purpose=/변경|휴강|취소/.test(what)?"일정 변경·취소":/모집|신청/.test(what)?"참여자 모집":/접근|이동/.test(what)?"안전·접근성 안내":"이용·행사 안내";
   if(k==="sns-post"&&what.includes("홈페이지"))fresh.v.where="복지관 홈페이지";
   if(k==="poster"||k==="cardnews"||k==="infographic")fresh.v.title=program;
   if(k==="image-prompt")fresh.v.scene=program+"의 "+what;
   ghScenarioDrafts[key]=fresh;
 }
 const left=app.querySelector(".gh-always-split .tin"),y=left?.scrollTop||0;
 const draft=ghScenarioDrafts[key];
 if(c==="promo"&&k==="sns-post"&&q.channel)draft.v.where=q.channel;
 if(c==="msg"){if(q.tone)draft.v.tone=q.tone;if(q.reader)draft.v.reader=q.reader;}
 ghScenarioRoute={k,cat:c,state:draft};current=t;
 renderTask(t);
 const shown=app.querySelector(".gh-always-split .tin");if(shown)shown.scrollTop=y;
}
const ghScenarioDrafts=Object.create(null);let ghScenarioRoute=null;

function renderCat(c){
  if((c==="msg"||c==="promo")&&options.catalog?.length){ghOpenScenario(c,ghDefaultScenario(c));return;}
  const list = TASKS.filter(t=>t.cat===c&&!t.hideOld);
  const district=!!GH_SECTOR_STATE[c]&&options.catalog&&options.catalog.length;
  app.innerHTML = `<div class="fade cat-${c}" style="display:flex;flex-direction:column;gap:18px">
    <button class="back b3d" type="button" data-home>← 처음으로</button>
    <div class="page-head"><p class="label">${district?"사업별 업무":list.length+"가지 업무"}</p><h2>${CAT_EM[c]} ${CATS[c].name}${MAN["cat-"+c]?` <button type="button" class="man-link" data-man="cat-${c}">📘 사용법</button>`:""}</h2><p>지금 상황과 가장 가까운 것을 눌러주세요.</p></div>
    ${district?ghDistrict(c)+'<details class="gh-existing-work"><summary>기존 작업 메뉴</summary>':""}<div class="list">${list.map(t=>rowHTML(t)).join("")}${c==="promo"?`<button class="row b3d cat-promo" type="button" data-goto="photo"><span class="dot" aria-hidden="true"></span><span class="em" aria-hidden="true">📷</span><span class="tx"><span class="t">활동 사진을 정리해 내려받고 싶어요</span><span class="s">활동 사진 올리기</span></span><span class="go" aria-hidden="true">→</span></button>`:""}</div>${district?"</details>":""}</div>`;
}

/* ---------- 업무 화면 ---------- */
function getVals(t){
  if(ghScenarioRoute&&ghScenarioRoute.k===t.id)return ghScenarioRoute.state;
  if(!values[t.id]){
    const v = {};
    (t.chips||[]).forEach(c=>{v[c.k]=c.opts[c.def||0]});
    (t.inputs||[]).forEach(i=>{v[i.k]=""});
    if(t.form){ v._form="없어요"; v._formText=""; }
    if(t.refimg){ v._ref="없어요"; v._refWhat="색감과 분위기"; v._refColors=""; v._refImg=""; }
    values[t.id] = {v, edited:false, text:null};
  }
  return values[t.id];
}


/* ---------- 바로 쓰는 완성 문구 ---------- */
const sent = s => { s=(s||"").trim(); if(!s) return ""; return /[.!?。~]$/.test(s) ? s : s+"."; };
const val = (v,k,ph) => (v[k]||"").trim() || ph;
/* 짧은 소식(예: 단풍 나들이)을 후원자 감사 문장으로 풀어 쓰기 */
function newsStory(raw,polite){
  const r=(raw||"").trim(); if(!r) return "[최근 시설 소식]";
  if(/[.!?。~]$/.test(r) || /(요|다|니다|어요|아요|해요|했어요)$/.test(r) || r.length>28) return sent(r);
  const w=r.replace(/\s+/g," ");
  const go=/(나들이|소풍|여행|견학|캠프|산책|구경|등산|체험|방문)$/.test(w);
  const party=/(파티|잔치|행사|축제|대회|송년회|생일|발표회|운동회|회)$/.test(w);
  const end=polite?"습니다":"어요";
  const verb= go ? `다녀왔${end}` : party ? `열었${end}` : `함께했${end}`;
  const thanks= polite ? "후원자님께서 보내주신 따뜻한 관심과 후원 덕분에" : "후원자님이 보내주신 따뜻한 마음 덕분에";
  const after= go ? (polite?"모두 함께 걷고 이야기 나누며 웃음이 끊이지 않는 하루를 보냈습니다.":"모두 함께 걷고 이야기 나누며 웃음이 끊이지 않는 하루를 보냈어요.")
            : party ? (polite?"서로 축하하고 음식을 나누며 마음까지 따뜻해지는 시간이었습니다.":"서로 축하하고 음식을 나누며 마음까지 따뜻해지는 시간이었어요.")
            : (polite?"이용자분들이 즐겁게 참여하며 뿌듯한 시간을 보냈습니다.":"이용자분들이 즐겁게 참여하며 뿌듯한 시간을 보냈어요.");
  return `${thanks} 저희 이용자분들이 행복하게 ${josa(w,"을","를")} ${verb}.\n${after}\n그 기쁜 소식을 후원자님께 꼭 전해드리고 싶었${polite?"습니다":"어요"}.`;
}
/* 짧은 단어·반말 메모를 감사 문장으로 다듬기 */
function spaceWord(w){ return String(w||"").trim().replace(/([가-힣])(나들이|여행|소풍|견학|캠프|체험|파티|잔치|행사|축제|교실|만들기)$/,"$1 $2"); }
function storyFix(raw,polite,present,noSubj){
  let s=String(raw||"").trim(); if(!s) return "";
  s=s.replace(/입소자(분)?들?/g,"이용자분들").replace(/입소자/g,"이용자분").replace(/[.!~]+$/,"");
  const E=polite?"습니다":"어요";
  const R=[[/좋아함$/,polite?(present?"좋아합니다":"좋아했습니다"):(present?"좋아해요":"좋아했어요")],[/(하고\s*있)음$/,"$1"+E],[/했음$/,"했"+E],[/함$/,present?(polite?"합니다":"해요"):"했"+E],[/이다$/,polite?"입니다":"이에요"],[/임$/,polite?"입니다":"이에요"]];
  let hit=false; for(const [re,to] of R){ if(re.test(s)){ s=s.replace(re,to); hit=true; break; } }
  if(!hit && /다$/.test(s)){ const c=s.charCodeAt(s.length-2); if(c>=0xAC00&&c<=0xD7A3&&(c-0xAC00)%28===20){ s=s.slice(0,-1)+E; hit=true; } }
  if(!hit && !/(요|니다|어|지)$/.test(s)) s = /(행복|기쁨|즐거움|웃음|만족)$/.test(s) ? `${s}이 가득한 시간이었${E}` : `${josa(s,"이","가")} 있었${E}`;
  if(!noSubj && !/(이용[인자]|모두|우리|저희|들이|님이|님은|분들|○○|^[가-힣]+(이|가|은|는)\s)/.test(s) && /(요|니다)$/.test(s)) s="이용자분들이 "+s;
  return s+".";
}
/* 짧은 단어를 후원자가 뿌듯해할 문장으로 풀기 */
function storyRich(raw,polite){
  const r=String(raw||"").trim(); if(!r) return "";
  const E=polite?"습니다":"어요";
  const w=r.replace(/[.!~]+$/,"").replace(/입소자(분)?들?/g,"이용자분들").replace(/입소자/g,"이용자분").trim();
  const isSentence=/(요|다|니다|음|함)$/.test(w) && w.length>=4;
  if(!isSentence){
    if(/(행복|기쁨|기뻐|즐거|웃음|신남|신나|좋아|만족|감동)/.test(w))
      return `보내주신 후원 덕분에 이용자분들의 얼굴에 행복한 웃음이 가득했${E}. 서로 마주 보며 기뻐하는 모습을 보면서, 후원자님의 나눔이 이분들의 하루를 얼마나 환하게 바꾸는지 다시 한번 느꼈${E}.`;
    if(/(나들이|여행|소풍|견학|캠프|산책|구경|등산|체험|방문)$/.test(w))
      return `보내주신 후원 덕분에 이용자분들과 함께 ${josa(spaceWord(w),"을","를")} 다녀올 수 있었${E}. 평소에 쉽게 가 보기 어려운 곳에서 새로운 경험을 하며 모두 환하게 웃었${E}.`;
    if(/(파티|잔치|행사|축제|생일|송년회)$/.test(w))
      return `보내주신 후원 덕분에 ${josa(spaceWord(w),"을","를")} 넉넉하게 준비할 수 있었${E}. 모두 함께 축하하며 잊지 못할 추억을 만들었${E}.`;
    if(/(식사|간식|밥|반찬|과일|고기|떡|케이크)$/.test(w))
      return `보내주신 후원 덕분에 이용자분들이 ${josa(w,"을","를")} 맛있게 나눠 먹었${E}. "맛있다"며 그릇을 싹 비우는 모습에 저희도 마음이 따뜻해졌${E}.`;
    return `보내주신 후원 덕분에 ${josa(w,"이","가")} 가능했${E}. 덕분에 이용자분들의 일상이 한결 풍성하고 든든해졌${E}.`;
  }
  if(/(행복|기쁨|기뻐|즐거|웃음|신나|좋아|만족|감동)/.test(w)) return `${storyFix(w,polite)} 얼굴마다 환한 웃음이 가득했고, 서로 마주 보며 기뻐하는 모습에 저희도 마음이 따뜻해졌${E}. 후원자님의 나눔이 이분들의 하루를 이렇게 환하게 바꾸고 있${E}.`;
  return `${storyFix(w,polite)} 후원자님의 나눔이 이렇게 이용자분들의 일상을 따뜻하게 바꾸고 있${E}.`;
}
/* 어려운 안내문을 쉬운 말로 (규칙 기반 초안) */
const EASY_W=[[/금주/g,"이번 주"],[/익일/g,"다음 날"],[/금일/g,"오늘"],[/명일/g,"내일"],[/경보음\s*(이\s*)?(발생|울릴)\s*(시|때)/g,"비상벨이 울리면"],[/경보음/g,"비상벨 소리"],[/(\S+)\s*발생\s*시/g,"$1이(가) 생기면"],[/직원의\s*안내에\s*따라/g,"직원 말을 잘 듣고"],[/안내에\s*따라/g,"안내를 잘 듣고"],[/신속히|신속하게/g,"빨리"],[/대피하시기\s*바랍니다|대피해\s*주시기\s*바랍니다|대피하십시오/g,"밖으로 나가요"],[/(소방\s*)?대피\s*훈련/g,"불이 났을 때 밖으로 나가는 연습"],[/대피/g,"피하기"],[/실시될\s*예정(이오니|이니|입니다|임)?/g,"있어요"],[/실시합니다|실시함/g,"해요"],[/실시/g,"하기"],[/예정이오니|예정이니/g,"예정이에요"],[/지참하시기\s*바랍니다|지참\s*바랍니다/g,"꼭 가져와요"],[/지참/g,"가져오기"],[/착용하시기\s*바랍니다/g,"꼭 입어요"],[/착용/g,"입기"],[/참석하시기\s*바랍니다/g,"꼭 와 주세요"],[/참석/g,"오기"],[/섭취/g,"먹기"],[/금지(합니다|됩니다)?/g,"하면 안 돼요"],[/유의하시기\s*바랍니다|유의\s*바랍니다/g,"조심해요"],[/유의/g,"조심"],[/소등/g,"불 끄기"],[/점검/g,"살펴보기"],[/협조\s*부탁드립니다|협조\s*바랍니다/g,"도와주세요"],[/하시기\s*바랍니다|해\s*주시기\s*바랍니다/g,"해 주세요"],[/바랍니다/g,"주세요"],[/문의/g,"궁금한 것"],[/귀가/g,"집에 가기"],[/일시/g,"날짜와 시간"]];
const EASY_GO={"듣고":"들어요","하고":"해요","가고":"가요","보고":"봐요","먹고":"먹어요","입고":"입어요","쓰고":"써요","챙기고":"챙겨요","씻고":"씻어요","끄고":"꺼요","닫고":"닫아요","열고":"열어요","마시고":"마세요","말고":"마세요"};
function easyText(orig,short){
  let t=String(orig||"").trim(); if(!t) return "[원래 안내 내용]을 적으면 쉬운 말로 바꿔 드려요.";
  EASY_W.forEach(([re,to])=>{ t=t.replace(re,to); });
  let parts=t.split(/(?<=[.!?])\s+|\n+|(?<=요)\s+(?=\S)|\s*(?:이오니|으니|하오니|하니|하며|이며)\s*/).map(s=>(s||"").trim()).filter(Boolean);
  const out=[];
  parts.forEach(p=>{
    p=p.replace(/[.!?]+$/,"");
    const m=p.match(/^(.*?)\s(\S+고)\s(.+)$/);
    if(m && EASY_GO[m[2]]){ out.push(`${m[1]} ${EASY_GO[m[2]]}`); p=m[3]; }
    out.push(p);
  });
  const fin=out.map(s=>{ s=s.trim().replace(/있$/,"있어요").replace(/없$/,"없어요").replace(/하$/,"해요").replace(/예정이$/,"예정이에요"); if(!/(요|세요|돼요|다)$/.test(s)) s=s.replace(/(이|가)?\s*있음$/,"이 있어요")+(/(요)$/.test(s)?"":"요"); return s.replace(/요요$/,"요").replace(/다$/,"어요")+"."; });
  const pic=s=>/비상벨|불|소방/.test(s)?"비상벨·소방차":/밖으로|피하/.test(s)?"문 밖으로 나가는 사람":/토요일|월요일|화요일|수요일|목요일|금요일|일요일|날짜|오늘|내일|주/.test(s)?"달력":/시간|시/.test(s)?"시계":/직원|말을/.test(s)?"직원이 손짓하는 모습":/먹|식사|간식/.test(s)?"밥상":/가져|챙/.test(s)?"가방":"";
  const list=(short?fin.slice(0,3):fin);
  return list.map((s,i)=>`${i+1}. ${s}${short?"":(pic(s)?`  [그림: ${pic(s)}]`:"")}`).join("\n");
}
/* 후원금 사용처를 자연스러운 문장으로 */
function wonFix(s){ return String(s||"").replace(/(\d[\d,.]*)\s*만\s*원/g,"$1만 원").replace(/(\d[\d,.]*)\s*원/g,(m,a)=>a+"원").trim(); }
function useItem(raw){
  let t=String(raw||"").trim(), amt="";
  const m=t.match(/[\s(]*(\d[\d,.]*\s*(만\s*)?원)\)?\s*$/); if(m){ amt=wonFix(m[1]); t=t.slice(0,m.index).trim(); }
  t=t.replace(/^(봄|여름|가을|겨울)(?=[가-힣]{2})/,"$1 ").replace(/([가-힣]{2})(구입|구매|마련|준비|교체|수리|지원|비용)$/,"$1 $2");
  t=spaceWord(t);
  const core=t.replace(/\s*(구입|구매|마련|준비|교체|비용|지원|비)$/,"").trim()||t;
  return {title:t, core, amt};
}
function useDesc(x,polite){
  const E=polite?"습니다":"어요", D=polite?"했습니다":"했어요", B=polite?"되었습니다":"되었어요";
  const w=x.title, c=x.core, a=x.amt?`${x.amt}을 들여 `:"";
  const R=[
   [/이불|담요|침구|매트리스|베개/, `이용자분들이 따뜻하고 편안하게 잠들 수 있도록 ${a}포근한 ${c}을(를) 마련${D}. 덕분에 올겨울을 한결 따뜻하게 보낼 수 있게 ${B}.`],
   [/난방|보일러|가스|전기|연료|등유/, `추운 날씨에도 집 안을 따뜻하게 지킬 수 있도록 ${a}난방비로 사용${D}. 이용자분들이 감기 걱정을 덜고 따뜻하게 지내고 있${E}.`],
   [/식사|식재료|장보기|반찬|쌀|김장|부식|식비/, `이용자분들의 건강한 밥상을 위해 ${a}신선한 식재료를 구입하는 데 사용${D}. 매일 함께 나누는 식사가 한층 풍성하고 든든해졌${E}.`],
   [/간식|과일|떡|케이크|음료|빵/, `${a}이용자분들이 함께 나눌 ${c}을(를) 준비${D}. 둘러앉아 나눠 먹으며 웃음꽃이 피는 시간을 보냈${E}.`],
   [/옷|의류|신발|외투|패딩|내복|양말|모자/, `계절에 맞는 ${c}을(를) ${a}마련${D}. 이용자분들이 날씨 걱정 없이 따뜻하고 단정하게 지낼 수 있게 ${B}.`],
   [/나들이|여행|소풍|견학|캠프|체험|공연|영화|관람|문화/, `이용자분들과 함께 ${josa(c,"을","를")} 다녀오는 데 ${a}필요한 비용으로 사용${D}. 평소에 하기 어려운 경험을 함께하며 소중한 추억을 만들었${E}.`],
   [/생일|파티|잔치|행사|송년|명절|추석|설날|축하/, `${josa(c,"을","를")} 준비하는 데 ${a}사용${D}. 모두 함께 축하하고 웃으며 마음까지 따뜻해지는 시간을 보냈${E}.`],
   [/세탁기|냉장고|티비|TV|tv|청소기|가전|가구|식탁|의자|침대|에어컨|선풍기|밥솥|전자레인지/, `생활에 꼭 필요한 ${josa(c,"을","를")} ${a}새로 마련${D}. 이용자분들의 생활이 더 편리하고 안전해졌${E}.`],
   [/생필품|생활용품|세제|휴지|위생|목욕|화장지|샴푸/, `생활에 꼭 필요한 생필품을 ${a}구입하는 데 사용${D}. 이용자분들이 더 깨끗하고 쾌적하게 생활하고 있${E}.`],
   [/병원|진료|건강|검진|약|치료|재활|의료/, `이용자분들의 건강을 지키는 데 ${a}사용${D}. 아픈 곳 없이 건강하게 지낼 수 있도록 앞으로도 꼼꼼히 챙기겠${E==="습니다"?"습니다":"어요"}.`],
   [/프로그램|교실|재료|강사|교육|수업|만들기|미술|음악|운동|체육|원예|텃밭/, `이용자분들이 즐겁게 참여하는 ${c} 활동에 ${a}사용${D}. 새로운 것을 배우고 스스로 해내는 기쁨을 함께 나눴${E}.`],
   [/수리|보수|도배|장판|공사|교체|페인트/, `${w}에 ${a}사용${D}. 집이 한결 깨끗하고 안전해져 이용자분들이 더 편안하게 지내고 있${E}.`]];
  for(const [re,t] of R){ if(re.test(w)) return t.replace(/(\S+)을\(를\)/g,(m,n)=>josa(n,"을","를")); }
  return `${josa(w,"을","를")} 위해 ${a}소중히 사용${D}. 이용자분들의 생활에 꼭 필요한 곳에 쓰였${E}.`;
}
function useExplain(w,polite){
  const E=polite?"습니다":"어요", go=/(나들이|여행|소풍|견학|캠프|산책|구경|등산|체험|방문)$/.test(w), party=/(파티|잔치|행사|축제|대회|송년회|생일)$/.test(w), buy=/(구입|구매|마련|교체|수리|설치)$/.test(w);
  const m=w.match(/^(.+?)\s*(구입|구매|마련|교체|수리|설치)$/);
  const a = go ? `이용자분들과 함께 ${josa(w,"을","를")} 다녀오는 데 사용했${E}.` : party ? `${josa(w,"을","를")} 여는 데 사용했${E}.` : m ? `${josa(m[1],"을","를")} ${m[2]}하는 데 사용했${E}.` : `${w}에 사용했${E}.`;
  const b = go ? `계절을 함께 느끼며 웃음 가득한 하루를 보냈${E}.` : party ? `모두 함께 축하하며 즐거운 시간을 보냈${E}.` : buy ? `이용자분들이 더 편안하게 생활할 수 있게 되었${E}.` : `이용자분들의 일상에 든든한 보탬이 되었${E}.`;
  return `   → ${a} ${b}`;
}
function useSentence(items,polite){
  const E=polite?"습니다":"어요";
  const one=w=>{ if(/(나들이|여행|소풍|견학|캠프|산책|구경|등산|체험|방문)$/.test(w)) return `이용자분들과 함께 ${josa(w,"을","를")} 다녀오는 데`;
    if(/(파티|잔치|행사|축제|대회|송년회|생일)$/.test(w)) return `${josa(w,"을","를")} 여는 데`;
    const m=w.match(/^(.+?)\s*(구입|구매|마련|교체|수리|설치)$/); if(m) return `${josa(m[1],"을","를")} ${m[2]}하는 데`;
    return `${w}에`; };
  const parts=items.slice(0,3).map(one);
  return `보내주신 후원금은 ${parts.join(", ")}${items.length>3?` 등`:""} 소중히 사용했${E}.`;
}
const PROMO_ORG="용인시기흥장애인복지관";
const PROMO_TONE={
 "따뜻하게":["함께한 활동 이야기를 따뜻한 마음으로 전합니다.","함께해 주신 분들께 마음 깊이 감사드립니다."],
 "부드럽게":["오늘은 복지관에서 있었던 일을 차분히 나눠 보려 해요.","읽어 주셔서 고마워요. 또 소식 전할게요."],
 "밝고 경쾌하게":["복지관에서 어떤 활동을 했을까요? 함께 살펴봐요!","함께해 주신 모든 분, 고맙습니다!"],
 "차분하게":["이번 활동에서 있었던 일을 정리했습니다.","참여해 주신 분들께 감사드립니다."],
 "쉽게":["복지관에서 한 일을 쉽게 알려 드려요.","글을 읽어 주셔서 고마워요."],
 "공식적이고 정중하게":["확인된 활동 내용을 아래와 같이 전해 드립니다.","참여해 주신 모든 분께 감사드립니다."]
};
function promoMemo(raw){
 const a=String(raw||"").trim().split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
 const title=a.find(x=>/^(제목|프로그램명|행사명)\s*[:：]/.test(x));
 return {title:title?title.replace(/^[^:：]+[:：]\s*/,""):"",lines:a.filter(x=>x!==title)};
}
function promoLine(s){return /[:：]/.test(s)?s:sent(s);}
function promoPost(v){
 const raw=String(v.act||"").trim(),empty=!raw,P=v._work?.program||"",org=PROMO_ORG;
 const meta={}, blocks={work:[],prep:[],steps:[],moment:[],reaction:[],thanks:[],next:[],photo:[]};
 const keys={
  "제목":"title","프로그램명":"title","행사명":"title","활동명":"title",
  "일시":"when","행사일시":"when","날짜":"when","장소":"where","참여대상":"who","참여인원":"count",
  "활동":"work","올릴활동":"work","활동내용":"work","준비":"prep","준비과정":"prep","진행":"steps","진행내용":"steps","과정":"steps",
  "기억에남는장면":"moment","기억에남는순간":"moment","한장면":"moment",
  "참여자반응":"reaction","참여자의반응":"reaction","반응":"reaction","참여자한마디":"reaction","소감":"reaction",
  "감사":"thanks","다음활동":"next","다음일정":"next","사진":"photo","사진설명":"photo"
 };
 let active="work";
 raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).forEach(line=>{
  const m=line.match(/^(?:[·•■-]\s*)?([^:：]{1,24})[:：]\s*(.*)$/),k=m&&keys[m[1].replace(/\s/g,"")];
  if(k){if(blocks[k]){active=k;if(m[2])blocks[k].push(m[2]);}else{meta[k]=m[2];active="work";}}
  else blocks[active].push(line);
 });
 const sentences=blocks.work.flatMap(x=>x.split(/(?<=[.!?。])\s+/));
 const name=meta.title||P||"복지관 활동 이야기",title=empty&&!P?"[올릴 활동]":name;
 const context=[meta.when,meta.where].filter(Boolean).join(" · ");
 const natural=s=>{
  if(/[.!?。…]$/.test(s)||/[:：]/.test(s))return s;
  if(/(?:요|다|함|음|됨|임)$/.test(s))return sent(s);
  if(s.length<25)return josa(s,"을","를")+" 진행했어요.";
  return sent(s);
 };
 const main=sentences[0]?natural(sentences[0]):empty?"이용자분들과 함께 [올릴 활동]을 진행했어요.":(meta.title||P?josa(name,"을","를")+" 진행했어요.":"");
 const prep=blocks.prep.map(sent).join("\n");
 const steps=sentences.slice(1).map(sent).concat(blocks.steps.map(sent)).join("\n");
 const moment=blocks.moment.map(sent).join("\n"),react=blocks.reaction.join("\n"),next=blocks.next.map(sent).join("\n"),thanks=blocks.thanks.map(sent).join("\n");
 const photo=blocks.photo.join(" · ");
 const tone=PROMO_TONE[v.tone]||PROMO_TONE["따뜻하게"];
 const tag=(meta.title||P).replace(/[^가-힣a-zA-Z0-9]/g,"").slice(0,28);
 const tags="#용인시기흥장애인복지관 #장애인복지관 #복지관소식"+(tag?" #"+tag:empty?" #올릴활동":"");
 const join=x=>x.filter(Boolean).join("\n\n");
 const facts=[meta.when&&"일시: "+meta.when,meta.where&&"장소: "+meta.where,meta.who&&"참여 대상: "+meta.who,meta.count&&"참여 인원: "+meta.count].filter(Boolean).join("\n");
 const short=join([title,main,tone[1]]);
 if(v.where==="인스타그램")return [
  ["인스타그램 원고",join(["📌 "+title,context,tone[0],[main,steps,moment,react].filter(Boolean).join("\n"),thanks||tone[1],tags])],
  ["인스타그램 짧은 원고",join([title,main,tags])]
 ];
 if(v.where==="카카오톡 채널")return [
  ["카카오톡 채널 원고",join(["["+org+" 소식] "+title,context,tone[0],[main,moment||react||steps].filter(Boolean).join("\n"),thanks||tone[1]])],
  ["카카오톡 한눈에 보기",short]
 ];
 if(v.where==="복지관 홈페이지")return [
  ["복지관 홈페이지 행사 후기",join(["["+org+" 소식] "+title,
   facts?"■ 활동 개요\n"+facts:empty?"■ 활동 개요\n[일시·장소·참여 대상]":"",
   "■ 진행 내용\n"+[main,prep,steps|| (empty?"[실제로 진행한 내용]":"")].filter(Boolean).join("\n"),
   moment||react?"■ 활동 결과·참여자 반응\n"+[moment,react].filter(Boolean).join("\n"):empty?"■ 활동 결과\n[확인된 결과나 반응]":"",
   photo?"[사진: "+photo+"]":empty?"[사진: 행사 현장]":"",
   next?"■ 다음 소식\n"+next:"",thanks||tone[1]])],
  ["홈페이지 목록용 요약",short]
 ];
 return [
  ["네이버 블로그 원고",join([title+" | "+org,"안녕하세요, "+org+"입니다. "+tone[0],
   "■ 오늘의 활동\n"+[context,main,photo?"[사진: "+photo+"]":empty?"[사진: 활동 모습]":""].filter(Boolean).join("\n"),
   prep||empty?"■ 준비하며\n"+(prep||"[활동 전에 준비한 내용이 있다면 적어 주세요.]"):"",
   steps||empty?"■ 이렇게 진행했어요\n"+(steps||"[활동 순서나 직접 해 본 일]"):"",
   moment||empty?"■ 기억에 남는 순간\n"+(moment||"[기억에 남는 장면을 한두 줄 적어 주세요.]"):"",
   react||empty?"■ 참여자분들의 한마디\n"+(react||"[공개해도 되는 실제 반응이 있다면 적어 주세요.]"):"",
   thanks?"■ 함께해 주신 분들\n"+thanks:empty?"■ 함께해 주신 분들\n[감사를 전할 분이나 단체가 있다면 적어 주세요.]":"",
   next?"■ 다음 소식\n"+next:"",tone[1],tags])],
  ["블로그 소개글",short]
 ];
}
function promoMonth(v){
 const d=promoMemo(v.events);if(!d.lines.length&&!d.title)d.lines=["[이번 달에 진행한 활동]","[다음에 알려 드릴 소식]"];if(!d.title&&v._work)d.title=v._work.program+" 소식";
 const lines={
  "보호자":["보호자님, 안녕하세요. 복지관에서 있었던 일을 전해 드립니다.","궁금한 점은 복지관에 문의해 주세요."],
  "참여자 가족":["가족 여러분, 안녕하세요. 복지관의 이번 달 활동을 나눕니다.","이번 달 이야기를 읽어 주셔서 고맙습니다."],
  "지역 주민":["이웃 여러분, 안녕하세요. 우리 동네 복지관 소식입니다.","앞으로도 동네에서 있었던 복지관 이야기를 전하겠습니다."],
  "후원자":["후원자님, 늘 관심을 가져 주셔서 감사합니다. 이번 달 복지관 소식을 전합니다.","보내 주신 관심과 응원에 감사드립니다."],
  "자원봉사자":["자원봉사자 여러분, 안녕하세요. 복지관의 이번 달 활동 소식을 알려 드립니다.","힘을 보태 주시는 모든 분께 감사드립니다."],
  "협력기관":["협력기관 담당자님께 이번 달 복지관 소식을 공유드립니다.","다음 활동에서도 필요한 소통을 이어가겠습니다."],
  "이용자":["여러분, 안녕하세요. 이번 달 복지관에서 있었던 일이에요.","더 알고 싶은 것은 복지관에 물어봐 주세요."]
 }[v.reader];
 const tone=PROMO_TONE[v.tone]||PROMO_TONE["따뜻하게"];
 return [[v.reader+"용 소식지 원고",[`[${PROMO_ORG}] ${d.title||"이달의 소식"}`,lines[0],d.lines.map(x=>"• "+promoLine(x)).join("\n"),lines[1]+" "+tone[1]].filter(Boolean).join("\n\n")]];
}
function promoNotice(v){
 const d=promoMemo(v.content);
 if(!d.lines.length&&!d.title)d.lines=v.purpose==="일정 변경·취소"?["기존 일정: [일시]","변경 일정: [일시 또는 취소 여부]","문의: [공식 문의처]"]:["일시: [날짜·시간]","장소: [장소]","참여 대상: [대상]","신청·문의: [방법과 공식 문의처]"];if(!d.title&&v._work)d.title=v._work.program+" · "+v._work.what;
 const lead=v.tone==="쉬운 말로"?"알아두면 좋은 내용을 아래에 정리했어요.":v.tone==="따뜻하게"?"참여하시기 편하도록 필요한 내용을 모았습니다.":"아래 내용을 확인해 주시기 바랍니다.";
 return [["복지관 안내문 원고",[`[${v.purpose}]${d.title?" "+d.title:""}`,`${v.reader} 여러분, 안녕하세요. ${PROMO_ORG}입니다. ${lead}`,d.lines.map(promoLine).join("\n"),PROMO_ORG].filter(Boolean).join("\n\n")]];
}
