 "회신기한":"due","답장기한":"due","기한":"due","마감":"due","안내시점":"due","문의":"contact","문의처":"contact","전화":"contact","전화번호":"contact","담당자전화번호":"contact","연락처":"contact","담당":"staff","담당자":"staff","담당자명":"staff",
