  return (deadline?deadline+"까지 ":"")+(a?(a.endsWith("지")?a:josa(a,"을","를")):"참여 여부를")+(friendly?" 편하게 알려 주세요.":easy?" 답장해 주세요.":" 회신해 주시면 감사하겠습니다.");
