   facts=[label("기존 일정",f.oldAt),label(cancelled?"변경 사항":"변경 일정",cancelled?(f.status||"취소"):infoTime||(includesMemo?"":"[바뀐 날짜·시간]")),label("만나는 장소",f.where||(!cancelled?"[장소]":"")),label("변경 이유",f.why),label("대안",f.alt)];
